import {reviewStatus} from './security';
/**
 * review.js - Race Start Review UI
 *
 * Bundled by the sailview webpack build so it shares auth cookies,
 * /assets/calibration/ images, and the viewer360 module.
 *
 * Data layout (same in dev and prod, served from S3 or webpack dev server):
 *   Analyze/events_index.json    — read-only, generated by find_starts.py:
 *                                  small per-event summaries + preview track,
 *                                  loaded eagerly. Filtered to type==='start'
 *                                  for this view.
 *   Analyze/Events/<id>.json     — read-only, generated by find_starts.py:
 *                                  heavy per-event payload (tracks, series,
 *                                  features, inferred line). Lazy-fetched on
 *                                  selectStart() and merged into the in-memory
 *                                  start record so existing field accesses
 *                                  (s.track, s.awa_series, ...) keep working.
 *   Analyze/Sessions/<basename>.json
 *                                  — read-only, generated by find_starts.py
 *                                  alongside events. Per-parquet decimated
 *                                  GPS track for the detail map's full-session
 *                                  backdrop. Lazy-fetched on selectStart()
 *                                  keyed by the event's parquet file name
 *                                  (e.g. ``2026-02-28T09_32.parquet`` ->
 *                                  ``Analyze/Sessions/2026-02-28T09_32.json``).
 *   Analyze/events_edits.json    — editable: per-event status/notes/trim
 *                                  overlay, keyed by event id, client-owned.
 *   Comments/index.json          — comments user registry (dynamic)
 *   Comments/<user>/comments.json — per-user comment files
 */

import '../css/review.css';
import * as viewer360 from './viewer360';
import * as shared from './shared';
import * as utils from './utils';
import * as sparkline from './sparkline';

// ---- State ----------------------------------------------------------------
let startsData = { starts: [] };
let editsData = { version: 1, edits: {} };
let selectedId = null;
// Per-event detail payload cache. Keyed by event id; value is the raw detail
// JSON (also merged onto the matching startsData.starts[i] in place so existing
// field reads keep working). A pending fetch stores its Promise so concurrent
// selectStart() calls coalesce.
const detailCache = new Map();
const detailPending = new Map();
// Per-session track cache. Keyed by parquet file name (the same ``s.file``
// stamped on every event from the same parquet); value is the parsed JSON.
const sessionCache = new Map();
const sessionPending = new Map();
const FILTER_STORAGE_KEY = 'review_filters_v2';

// ---- Kind enum ------------------------------------------------------------
// Flat event-kind values produced by find_starts.py. ``other`` covers
// ambiguous starts and ambiguous roundings; default-hidden in the filter UI.
const ALL_KINDS = ['start', 'windward_rounding', 'leeward_rounding', 'tack', 'gybe', 'other'];
const DEFAULT_KIND_SET = new Set(['start', 'windward_rounding', 'leeward_rounding', 'tack', 'gybe']);

function kindLabel(kind) {
    return {
        start: 'start',
        windward_rounding: 'windward rounding',
        leeward_rounding: 'leeward rounding',
        tack: 'tack',
        gybe: 'gybe',
        other: 'other',
    }[kind] || kind || 'event';
}

function kindBadgeClass(kind) {
    return `badge-kind-${String(kind || 'other').replace(/_/g, '-')}`;
}

const MONTH_ABBR = [
    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
];
let detailMap = null;
let detailMapLayers = {};
let charts = {};
let detailScrubberMarker = null;
let detailFullTrack = null;
let windViewMode = true;
let activeTab = 'starts'; // 'starts' | 'comments'
let commentsCache = null; // flat list from shared.loadAllComments

// Day picker: null means "All days"; otherwise YYYY-MM-DD (Pacific-local).
// Replaces the old #filter-day <select>; the day-picker popup is the sole UI
// for switching days. URL grammar still uses ?day=YYYY-MM-DD or omits it for
// the all-days view, so deep links from older builds keep working.
let selectedDay = null;

// AIS overlay state — per-start data is loaded lazily on selection.
let aisBoats = null;             // array loaded from Analyze/AIS/<id>.json
let aisCurrentStartId = null;    // guards against stale async responses
let aisEnabled = true;
let aisLayers = {};              // per-MMSI { trail, marker, label } — updated in place on scrub
const AIS_TRAIL_SAMPLES = 2;     // real samples drawn behind the interpolated current position
const AIS_MAX_GAP_SEC = 60;      // don't interpolate or render across a gap bigger than this

// Sailview-style overlay: focused AWA/SPD/HDG/TWS instruments + wind-up mini
// map. The BoatView is (re)constructed whenever a new clip's log finishes
// loading, since it needs the full lat/lon/hdg arrays.
const OVERLAY_FIELDS = [
    {channel: 'awa', unit: '°',   decimals: 0},
    {channel: 'spd', unit: 'kt',  decimals: 1},
    {channel: 'hdg', unit: '°',   decimals: 0},
    {channel: 'tws', unit: 'kt',  decimals: 1},
    {channel: 'heel', unit: '°',  decimals: 0},
];
const OVERLAY_SPARK_WINDOW_MS = 30_000;
// Shared start-review window used by the detail map, scrubber, and overlay.
const START_WINDOW_PRE_SEC = 300;
const START_WINDOW_POST_SEC = 600;
// Focus the map on the event and early beat, not the whole +10 minute review
// window. The gun is anchored high so the pre-event box fills most of the map.
const MAP_FOCUS_PRE_SEC = 300;
const MAP_FOCUS_POST_SEC = 180;
const MAP_EVENT_TOP_FRACTION = 0.30;
let overlayBoatView = null;
let overlayBasename = null;
let overlayRows = null;
let overlayMapSvg = null;
let overlayFrame = null;

// ---- URL state ------------------------------------------------------------
// review.html navigation flows through the URL: every meaningful state
// transition (event selection, filter toggle, scrub, tab switch) writes to
// ``window.location`` so reload restores the view and copy/paste produces a
// shareable deep link.
//
// Grammar:
//   ?event=<id>            selected event id; legacy ``?start=<id>`` accepted
//   &t=<sec>               scrubber position (float seconds; default 0)
//   &kind=<k1>,<k2>,...    multi-select kind filter; default = all kinds
//                          except 'other' (omitted from URL when at default)
//   &day=<YYYY-MM-DD>      day filter; default 'all'
//   &status=<s>            status filter; default 'all'
//   &sort=<key>            sort key; default 'date'
//   &tab=<events|comments> active tab; default 'events'
//
// pushState is used only for event-selection (so back/forward steps through
// distinct events). All other state changes use replaceState so the history
// stack stays clean.
const URL_TAB_EVENTS = 'events';
const URL_TAB_COMMENTS = 'comments';
let currentUrlState = {
    event: null,
    t: 0,
    kindSet: new Set(DEFAULT_KIND_SET),
    day: 'all',
    status: 'all',
    sort: 'date',
    tab: URL_TAB_EVENTS,
};
let popstateInProgress = false;
let scrubUrlDebounceTimer = null;

function _kindSetEquals(a, b) {
    if (a.size !== b.size) return false;
    for (const v of a) if (!b.has(v)) return false;
    return true;
}

function parseUrlState() {
    const p = new URLSearchParams(window.location.search);
    const event = p.get('event') || p.get('start') || null; // legacy alias
    const tRaw = p.get('t');
    const t = tRaw != null && tRaw !== '' && Number.isFinite(parseFloat(tRaw))
        ? parseFloat(tRaw) : 0;
    const kindRaw = p.get('kind');
    const kindSet = kindRaw != null
        ? new Set(kindRaw.split(',').map(s => s.trim()).filter(Boolean))
        : new Set(DEFAULT_KIND_SET);
    const day = p.get('day') || 'all';
    const status = p.get('status') || 'all';
    const sort = p.get('sort') || 'date';
    let tab = p.get('tab') || URL_TAB_EVENTS;
    if (tab !== URL_TAB_EVENTS && tab !== URL_TAB_COMMENTS) tab = URL_TAB_EVENTS;
    return {event, t, kindSet, day, status, sort, tab};
}

function buildUrl(state) {
    const p = new URLSearchParams();
    if (state.event) p.set('event', state.event);
    if (state.t && Number.isFinite(state.t) && Math.abs(state.t) >= 0.5) {
        p.set('t', String(Math.round(state.t)));
    }
    if (state.kindSet && !_kindSetEquals(state.kindSet, DEFAULT_KIND_SET)) {
        // Sort for stable URLs; canonical-order makes diffs cleaner.
        const ks = ALL_KINDS.filter(k => state.kindSet.has(k));
        if (ks.length) p.set('kind', ks.join(','));
        else p.set('kind', '');  // explicit empty = "match nothing"
    }
    if (state.day && state.day !== 'all') p.set('day', state.day);
    if (state.status && state.status !== 'all') p.set('status', state.status);
    if (state.sort && state.sort !== 'date') p.set('sort', state.sort);
    if (state.tab && state.tab !== URL_TAB_EVENTS) p.set('tab', state.tab);
    const qs = p.toString();
    return window.location.pathname + (qs ? `?${qs}` : '');
}

function _mergeState(patch) {
    const merged = {...currentUrlState, ...patch};
    if (patch && Object.prototype.hasOwnProperty.call(patch, 'kindSet') && patch.kindSet) {
        merged.kindSet = patch.kindSet instanceof Set
            ? new Set(patch.kindSet) : new Set(patch.kindSet);
    } else {
        merged.kindSet = new Set(currentUrlState.kindSet);
    }
    return merged;
}

function pushUrl(patch) {
    if (popstateInProgress) return;
    const next = _mergeState(patch);
    currentUrlState = next;
    history.pushState(null, '', buildUrl(next));
}

function replaceUrl(patch) {
    if (popstateInProgress) return;
    const next = _mergeState(patch);
    currentUrlState = next;
    history.replaceState(null, '', buildUrl(next));
}

// ---- Boot -----------------------------------------------------------------
function fetchJSON(wwwPath) {
    if (wwwPath === 'Analyze/events_edits.json') return shared.readDataJSON(wwwPath);
    return new Promise((resolve, reject) => {
        let url = shared.dataGetUrl(wwwPath);
        if (utils.isLocal() && wwwPath.startsWith('Analyze/')) {
            url += (url.includes('?') ? '&' : '?') + `v=${Date.now()}`;
        }
        utils.getJSON(url, (err, data) => {
            if (err) reject(new Error(`fetch ${wwwPath} failed: ${err}`));
            else resolve(data);
        });
    });
}

/**
 * Project an events_index.json entry into the legacy start-shaped object the
 * rest of review.js expects. Adds back-compat
 * aliases for window/time field names and surfaces summary fields at the
 * top level. ``preview_track`` is exposed as ``track`` so the card
 * mini-map renders before the detail file loads; the full track will
 * overwrite it once ``ensureDetail()`` resolves.
 */
function asStartView(ev) {
    const summary = ev.summary || {};
    return {
        id: ev.id,
        kind: ev.kind,
        date: ev.date,
        file: ev.file,
        race_id: ev.race_id || null,
        label: ev.label || null,
        status: ev.status || 'pending',
        notes: ev.notes || '',
        confidence: ev.confidence,
        start_confidence: ev.start_confidence ?? summary.start_confidence,
        rounding_confidence: ev.rounding_confidence ?? summary.rounding_confidence,
        review_priority: ev.review_priority || summary.review_priority || 'medium',
        tack_count: ev.tack_count ?? summary.tack_count,
        gybe_count: ev.gybe_count ?? summary.gybe_count,
        // Compatibility aliases for older start-shaped UI helpers, where
        // these were the canonical names. Cheaper to alias once than to
        // refactor every read site.
        start_time_unix: ev.t_key_unix,
        window_begin: ev.t_start_unix,
        window_end: ev.t_end_unix,
        first_beat_end_unix: ev.t_end_unix,
        score_v2: summary.score_v2,
        score_legacy: summary.score_legacy,
        possible_ocs_return: summary.possible_ocs_return,
        // Maneuver-card metrics. Surfaced from index summary so the card
        // renders without a detail fetch; null on non-maneuver events.
        // Recovery is SPD-based (wind-direction-independent — what the
        // helmsman feels); distance/time lost is VMG-based (race-tactical).
        direction: summary.direction,
        hdg_change: summary.hdg_change,
        duration_s: summary.duration_s,
        entry_spd_kts: summary.entry_spd_kts,
        entry_vmg_kts: summary.entry_vmg_kts,
        spd_recovery_s_80: summary.spd_recovery_s_80,
        spd_recovery_s_90: summary.spd_recovery_s_90,
        time_below_80_spd_s: summary.time_below_80_spd_s,
        distance_lost_m: summary.distance_lost_m,
        time_lost_s: summary.time_lost_s,
        min_spd_kts: summary.min_spd_kts,
        max_yaw_rate_deg_s: summary.max_yaw_rate_deg_s,
        twa_symmetry_deg: summary.twa_symmetry_deg,
        // ``track`` is overwritten by the full per-event track once detail
        // loads; until then the decimated preview keeps the card alive.
        track: ev.preview_track || [],
    };
}

/**
 * Lazy-fetch the per-event detail payload and merge its fields onto the
 * matching in-memory start record. Concurrent calls for the same id share
 * one in-flight request. Resolves with the detail object (or null if the
 * fetch fails — callers should treat that as a soft error).
 */
function ensureDetail(id) {
    if (detailCache.has(id)) return Promise.resolve(detailCache.get(id));
    if (detailPending.has(id)) return detailPending.get(id);
    const p = fetchJSON(`Analyze/Events/${id}.json`)
        .then((detail) => {
            detailCache.set(id, detail);
            detailPending.delete(id);
            const s = (startsData.starts || []).find(x => x.id === id);
            if (s && detail) {
                // Merge heavy fields onto the start view. Preserve fields
                // already on ``s`` (status/notes from edits, top-level
                // confidence) by letting Object.assign clobber only what
                // detail provides.
                Object.assign(s, detail);
            }
            return detail;
        })
        .catch((err) => {
            detailPending.delete(id);
            console.error(`detail load failed for ${id}:`, err);
            return null;
        });
    detailPending.set(id, p);
    return p;
}

/**
 * Lazy-fetch the per-session track for a parquet file. Replaces the old
 * eager full-track load — we now only fetch the session for the
 * currently-selected event. Concurrent calls for the same file share one
 * in-flight request; the first selectStart in a session warms the cache
 * and subsequent ones are synchronous.
 */
function ensureSession(file) {
    if (!file) return Promise.resolve(null);
    if (sessionCache.has(file)) return Promise.resolve(sessionCache.get(file));
    if (sessionPending.has(file)) return sessionPending.get(file);
    const basename = file.replace(/\.parquet$/, '');
    const p = fetchJSON(`Analyze/Sessions/${basename}.json`)
        .then((session) => {
            sessionCache.set(file, session);
            sessionPending.delete(file);
            return session;
        })
        .catch((err) => {
            sessionPending.delete(file);
            console.error(`session load failed for ${file}:`, err);
            sessionCache.set(file, null);   // negative-cache so we don't refetch on every render
            return null;
        });
    sessionPending.set(file, p);
    return p;
}

async function boot() {
    if (!shared.checkAuthorization()) {
        utils.redirectWithParams('login.html', window.location.pathname);
        return;
    }

    try {
        const eventsDoc = await fetchJSON('Analyze/events_index.json');
        const events = (eventsDoc && eventsDoc.events) || [];
        startsData = {
            starts: events
                .map(asStartView),
        };
    } catch (e) {
        const msg = `Could not load events_index.json (${e.message}).

First generate the review data:
  conda run -n sailing python Analyze/find_starts.py --days 365

Then (re)start the dev server from Src/:
  npm run start`;
        document.getElementById('detail-empty').innerHTML =
            `<pre style="font-size:12px;color:#8b949e;text-align:left;white-space:pre-wrap">${utils.htmlEncode(msg)}</pre>`;
        console.error(e);
        return;
    }

    // Load the small edits overlay and merge on top of the generated start records.
    try {
        const edits = await fetchJSON('Analyze/events_edits.json');
        if (edits && edits.edits) editsData = edits;
    } catch (e) {
        console.log('no events_edits.json yet (ok on first run)');
    }
    applyEditsToStarts();

    // URL is authoritative for navigation state. Parse first, then apply to
    // UI controls and currentUrlState before renderAll() runs so the filter
    // / sort / status / tab dropdowns reflect the URL on first paint.
    const urlState = parseUrlState();
    currentUrlState = urlState;

    const setSelectValue = (id, value) => {
        if (!value) return;
        const el = document.getElementById(id);
        if (el && Array.from(el.options).some(o => o.value === value)) el.value = value;
    };
    setSelectValue('filter-status', urlState.status);
    setSelectValue('sort-by', urlState.sort);
    applyKindSetToDom(urlState.kindSet);

    // Day selection precedence: explicit ?day= in URL > saved localStorage >
    // most-recent-day-with-events. On first visit (no URL param, no saved
    // state), default to the most recent day so the user lands on something
    // populated instead of an "All days" mega-list.
    const urlSP = new URLSearchParams(window.location.search);
    if (urlSP.has('day')) {
        selectedDay = urlState.day && urlState.day !== 'all' ? urlState.day : null;
    } else {
        const saved = loadFilterState();
        if (saved.day === 'all') {
            selectedDay = null;
        } else if (saved.day && (startsData.starts || []).some(s => localDay(s) === saved.day)) {
            selectedDay = saved.day;
        } else {
            // Most-recent day; falls back to null if startsData is empty.
            const days = (startsData.starts || []).map(s => localDay(s)).filter(Boolean);
            days.sort();
            selectedDay = days.length ? days[days.length - 1] : null;
        }
        currentUrlState = {...currentUrlState, day: selectedDay || 'all'};
    }
    populateDayPicker();
    refreshDayPickerLabel();
    if (urlState.tab === URL_TAB_COMMENTS) activeTab = 'comments';
    document.querySelectorAll('.tab-btn').forEach(b =>
        b.classList.toggle('active', b.dataset.tab === activeTab));
    document.querySelectorAll('[data-tab-content]').forEach(el => {
        el.style.display = el.dataset.tabContent === activeTab ? '' : 'none';
    });

    if (urlState.event) {
        const targetStart = (startsData.starts || []).find(s => s.id === urlState.event);
        if (targetStart) {
            selectedId = urlState.event;
            console.log(`[review] loading event from URL: ${urlState.event}`);
            // If the URL-target's kind is filtered out by the active kindSet
            // (the recipient of a shared link defaults to all-except-other,
            // but the link may point at an ``other`` event), expand the set
            // so the event is visible in the list and syncSelectionWithVisibleStarts
            // doesn't kick selectedId to some unrelated newest visible event.
            if (targetStart.kind && !urlState.kindSet.has(targetStart.kind)) {
                urlState.kindSet.add(targetStart.kind);
                currentUrlState = urlState;
                applyKindSetToDom(urlState.kindSet);
            }
        }
    }

    renderAll();

    // Deep-link boot: renderAll() fell into the renderDetail-only branch
    // (autoSelected is false because selectedId already matches a visible
    // event), which doesn't load the per-event detail JSON or the session
    // backdrop. Kick those off here and re-render once they arrive so the
    // start line, charts, and full-track polylines paint without requiring
    // a manual nav-away-and-back. ensureDetail/ensureSession are cached.
    if (selectedId) {
        const s = (startsData.starts || []).find(x => x.id === selectedId);
        const sessionPromise = s ? ensureSession(s.file) : Promise.resolve(null);
        Promise.all([ensureDetail(selectedId), sessionPromise]).then(([detail, session]) => {
            if (selectedId !== urlState.event) return;
            if (detail || session) renderDetail(selectedId);
        });
    }

    // If we have a time parameter, seek to it after the video loads
    if (urlState.event && urlState.t && selectedId) {
        const seekTime = urlState.t;
        if (!isNaN(seekTime)) {
            setTimeout(() => {
                const scrubber = document.getElementById('detail-scrubber-range');
                if (scrubber) {
                    scrubber.value = seekTime;
                    onDetailScrub();
                }
            }, 1000);
        }
    }

    // Kick off comments load in the background so the Comments tab is instant when opened.
    shared.loadAllComments((_, list) => {
        commentsCache = list || [];
        if (activeTab === 'comments') renderCommentsList();
        if (selectedId) renderStartComments(selectedId);
    });
}

// Parse a start-id ("YYYY-MM-DDTHH_MM", UTC, minute precision) to a unix
// timestamp. Returns null if it doesn't look like an id.
function startIdToUnix(id) {
    if (typeof id !== 'string') return null;
    const m = id.match(/^(\d{4}-\d{2}-\d{2})T(\d{2})_(\d{2})$/);
    if (!m) return null;
    const ms = Date.parse(`${m[1]}T${m[2]}:${m[3]}:00Z`);
    return Number.isFinite(ms) ? ms / 1000 : null;
}

// Detector tweaks (e.g. tightening the candidate-step from 10s→5s in Phase C)
// can shift a start's minute-rounded id by ±1 minute, orphaning hand-labels
// keyed by the old id. We rebind any unmatched edit to the nearest start
// within FUZZY_REBIND_WINDOW_S (same date), so historical discards/confirms
// keep applying after detector changes.
const FUZZY_REBIND_WINDOW_S = 90;

function applyEditsToStarts() {
    const edits = editsData.edits || {};
    const starts = startsData.starts || [];
    const consumed = new Set();

    starts.forEach(s => {
        const e = edits[s.id];
        if (!e) return;
        consumed.add(s.id);
        if (e.status != null) s.status = reviewStatus(e.status);
        if (e.notes != null) s.notes = e.notes;
        if (e.trim_start_s != null) s.trim_start_s = e.trim_start_s;
        if (e.trim_end_s != null) s.trim_end_s = e.trim_end_s;
    });

    // Pass 2: fuzzy rebind orphaned edits to the nearest start within the
    // window. Skip starts that already received an exact-id edit.
    const claimed = new Set([...consumed]);
    Object.keys(edits).forEach(editId => {
        if (consumed.has(editId)) return;
        const editUnix = startIdToUnix(editId);
        if (editUnix == null) return;
        const editDate = editId.slice(0, 10);

        let best = null;
        let bestDt = Infinity;
        starts.forEach(s => {
            if (claimed.has(s.id)) return;
            if (s.date !== editDate) return;
            const dt = Math.abs((s.start_time_unix || 0) - editUnix);
            if (dt < bestDt) { bestDt = dt; best = s; }
        });
        if (!best || bestDt > FUZZY_REBIND_WINDOW_S) return;

        const e = edits[editId];
        if (e.status != null) best.status = reviewStatus(e.status);
        if (e.notes != null) best.notes = e.notes;
        if (e.trim_start_s != null) best.trim_start_s = e.trim_start_s;
        if (e.trim_end_s != null) best.trim_end_s = e.trim_end_s;
        claimed.add(best.id);
        console.warn(`[review] rebound orphaned edit ${editId} → ${best.id} (Δ=${bestDt.toFixed(0)}s)`);
    });
}

function upsertEdit(id, patch) {
    if (!editsData.edits) editsData.edits = {};
    const prev = editsData.edits[id] || {};
    const merged = {
        ...prev,
        ...patch,
        updated_ts: Math.floor(Date.now() / 1000),
    };
    editsData.edits[id] = merged;
    editsData.version = 1;
    editsData.updated_ts = merged.updated_ts;
}

// ---- Rendering ------------------------------------------------------------
function renderAll() {
    renderStats();
    const starts = getFilteredSorted();
    const autoSelected = syncSelectionWithVisibleStarts(starts);
    if (activeTab === 'comments') {
        renderCommentsList();
    } else {
        renderList(starts);
    }
    if (selectedId) {
        // Day-filter changes flip selectedId via syncSelectionWithVisibleStarts;
        // route through selectStart so the new event's session backdrop
        // (Sessions/<basename>.json) actually loads. renderDetail alone reads
        // sessionCache and silently skips the light-blue full-day track.
        if (autoSelected) selectStart(selectedId);
        else renderDetail(selectedId);
        if (autoSelected) requestAnimationFrame(scrollSelectedCardIntoView);
        return;
    }
    document.getElementById('detail-empty').textContent = '← Select a start from the list to inspect it.';
    document.getElementById('detail-empty').style.display = '';
    document.getElementById('detail-content').style.display = 'none';
}

function renderStats() {
    const starts = startsData.starts || [];
    const confirmed = starts.filter(s => s.status === 'confirmed').length;
    const pending = starts.filter(s => s.status === 'pending').length;
    const discarded = starts.filter(s => s.status === 'discarded').length;
    document.getElementById('stat-total').textContent = starts.length;
    document.getElementById('stat-confirmed').textContent = confirmed;
    document.getElementById('stat-pending').textContent = pending;
    document.getElementById('stat-discarded').textContent = discarded;
}

// Pacific-local YYYY-MM-DD for an event. The JSON ``s.date`` is UTC (it
// matches the UTC-stamped event id, which the edit fuzzy-rebind relies on),
// but cards render via formatDate() in America/Los_Angeles — bucketing the
// day filter by UTC orphans evening-Pacific events under the next UTC day.
function localDay(s) {
    if (!s || !s.start_time_unix) return s && s.date ? s.date : '';
    return viewer360.wallClockInTz(s.start_time_unix * 1000, 'America/Los_Angeles').slice(0, 10);
}

// Build (or rebuild) the day-picker popup tree: Year > Month > Day, where
// Year and Month are <details>/<summary> and Day is a clickable button.
// Latest year + last 2 calendar months auto-open; clicking a day calls
// setSelectedDay and closes the popup. Idempotent — safe to call after the
// data set changes (currently a one-shot load, but keep the contract clean).
function populateDayPicker() {
    const panel = document.getElementById('day-picker-panel');
    if (!panel) return;
    panel.innerHTML = '';

    const counts = new Map();
    (startsData.starts || []).forEach(s => {
        const day = localDay(s);
        if (!day) return;
        counts.set(day, (counts.get(day) || 0) + 1);
    });

    // "All days" entry — escape hatch for cross-day analysis.
    const allBtn = document.createElement('button');
    allBtn.type = 'button';
    allBtn.className = `dp-item dp-item-all${selectedDay ? '' : ' selected'}`;
    allBtn.dataset.day = '';
    allBtn.innerHTML =
        `<span class="dp-day-label">All days</span>` +
        `<span class="dp-day-count">${counts.size ? Array.from(counts.values()).reduce((a, b) => a + b, 0) : 0}</span>`;
    allBtn.addEventListener('click', () => { setSelectedDay(null); closeDayPicker(); });
    panel.appendChild(allBtn);

    // Group day keys (YYYY-MM-DD) into year > month > [day, ...].
    const byYear = new Map();
    Array.from(counts.keys()).forEach(ymd => {
        if (ymd.length < 10) return;
        const y = ymd.slice(0, 4);
        const m = ymd.slice(5, 7);
        const d = ymd.slice(8, 10);
        if (!byYear.has(y)) byYear.set(y, new Map());
        const months = byYear.get(y);
        if (!months.has(m)) months.set(m, []);
        months.get(m).push(d);
    });

    const years = [...byYear.keys()].sort().reverse();
    if (years.length === 0) return;
    const latestYear = years[0];

    const allYM = [];
    byYear.forEach((months, y) => months.forEach((_, m) => allYM.push(`${y}-${m}`)));
    allYM.sort();
    const openMonths = new Set(allYM.slice(-2));

    for (const y of years) {
        const yDetails = document.createElement('details');
        yDetails.className = 'vp-year';
        if (y === latestYear || (selectedDay && selectedDay.startsWith(`${y}-`))) {
            yDetails.open = true;
        }
        const ySummary = document.createElement('summary');
        const months = byYear.get(y);
        let yc = 0;
        months.forEach((days, m) => days.forEach(d => yc += counts.get(`${y}-${m}-${d}`) || 0));
        ySummary.innerHTML =
            `<span class="vp-name">${y}</span>` +
            `<span class="vp-count">${yc}</span>`;
        yDetails.appendChild(ySummary);

        const monthKeys = [...months.keys()].sort().reverse();
        for (const m of monthKeys) {
            const ymKey = `${y}-${m}`;
            const monthAbbr = MONTH_ABBR[parseInt(m, 10) - 1] || m;
            const days = months.get(m).slice().sort().reverse();

            const mDetails = document.createElement('details');
            mDetails.className = 'vp-month';
            if (openMonths.has(ymKey) || (selectedDay && selectedDay.startsWith(`${ymKey}-`))) {
                mDetails.open = true;
            }
            const mSummary = document.createElement('summary');
            let mc = 0;
            days.forEach(d => mc += counts.get(`${y}-${m}-${d}`) || 0);
            mSummary.innerHTML =
                `<span class="vp-name">${monthAbbr}</span>` +
                `<span class="vp-count">${mc}</span>`;
            mDetails.appendChild(mSummary);

            for (const d of days) {
                const ymd = `${y}-${m}-${d}`;
                const dBtn = document.createElement('button');
                dBtn.type = 'button';
                dBtn.className = 'dp-item';
                dBtn.dataset.day = ymd;
                if (ymd === selectedDay) dBtn.classList.add('selected');
                dBtn.innerHTML =
                    `<span class="dp-day-label">${monthAbbr} ${d}</span>` +
                    `<span class="dp-day-count">${counts.get(ymd) || 0}</span>`;
                dBtn.addEventListener('click', () => {
                    setSelectedDay(ymd);
                    closeDayPicker();
                });
                mDetails.appendChild(dBtn);
            }
            yDetails.appendChild(mDetails);
        }
        panel.appendChild(yDetails);
    }
}

// ---- Day picker open/close + selection ------------------------------------
function openDayPicker() {
    const panel = document.getElementById('day-picker-panel');
    const root = document.getElementById('day-picker');
    if (!panel || !root) return;
    panel.hidden = false;
    root.classList.add('open');
    const sel = panel.querySelector('.dp-item.selected');
    if (sel) sel.scrollIntoView({block: 'center'});
}

function closeDayPicker() {
    const panel = document.getElementById('day-picker-panel');
    const root = document.getElementById('day-picker');
    if (!panel || !root) return;
    panel.hidden = true;
    root.classList.remove('open');
}

function setSelectedDay(day) {
    selectedDay = day || null;
    refreshDayPickerLabel();
    document.querySelectorAll('#day-picker-panel .dp-item.selected')
        .forEach(el => el.classList.remove('selected'));
    const target = selectedDay
        ? document.querySelector(`#day-picker-panel .dp-item[data-day="${selectedDay}"]`)
        : document.querySelector('#day-picker-panel .dp-item-all');
    if (target) target.classList.add('selected');
    saveFilterState();
    replaceUrl({...currentUrlState, day: selectedDay || 'all'});
    // Day change usually invalidates the current selection — let renderAll's
    // syncSelectionWithVisibleStarts pick the newest event in the new day.
    renderAll();
}

function refreshDayPickerLabel() {
    const labelEl = document.querySelector('#day-picker .dp-label');
    const countEl = document.querySelector('#day-picker .dp-count');
    if (!labelEl) return;
    if (!selectedDay) {
        const total = (startsData.starts || []).length;
        labelEl.textContent = 'All days';
        if (countEl) countEl.textContent = total ? `· ${total}` : '';
        return;
    }
    // Format YYYY-MM-DD as "Apr 29, 2026" using the same MONTH_ABBR table.
    const y = selectedDay.slice(0, 4);
    const m = MONTH_ABBR[parseInt(selectedDay.slice(5, 7), 10) - 1] || selectedDay.slice(5, 7);
    const d = selectedDay.slice(8, 10);
    labelEl.textContent = `${m} ${d}, ${y}`;
    const count = (startsData.starts || []).filter(s => localDay(s) === selectedDay).length;
    if (countEl) countEl.textContent = count ? `· ${count}` : '';
}

function loadFilterState() {
    try {
        return JSON.parse(localStorage.getItem(FILTER_STORAGE_KEY) || '{}') || {};
    } catch (e) {
        return {};
    }
}

function saveFilterState() {
    const state = {
        status: document.getElementById('filter-status')?.value || 'all',
        kindSet: Array.from(getKindSetFromDom()),
        day: selectedDay || 'all',
        sort: document.getElementById('sort-by')?.value || 'date',
    };
    try {
        localStorage.setItem(FILTER_STORAGE_KEY, JSON.stringify(state));
    } catch (e) {
        // Non-fatal; filters just won't persist across reloads.
    }
}

function restoreFilterState() {
    const state = loadFilterState();
    const setValue = (id, value) => {
        if (!value) return;
        const el = document.getElementById(id);
        if (el && Array.from(el.options).some(o => o.value === value)) el.value = value;
    };
    setValue('filter-status', state.status);
    setValue('sort-by', state.sort);
    if (Array.isArray(state.kindSet)) applyKindSetToDom(new Set(state.kindSet));
    // selectedDay isn't a DOM element; URL state takes priority during boot,
    // so don't override it here. localStorage is only consulted for the
    // initial day default if the URL didn't specify one (handled at boot).
}

function onFilterChanged() {
    saveFilterState();
    replaceUrl({...currentUrlState, ...readFilterStateFromDom()});
    renderAll();
}

// ---- Kind filter DOM helpers ----------------------------------------------
function getKindSetFromDom() {
    const checks = document.querySelectorAll('.kind-filter-check');
    if (!checks.length) return new Set(DEFAULT_KIND_SET);
    const out = new Set();
    checks.forEach(c => { if (c.checked) out.add(c.value); });
    return out;
}

function applyKindSetToDom(kindSet) {
    const checks = document.querySelectorAll('.kind-filter-check');
    if (!checks.length) return;
    checks.forEach(c => { c.checked = kindSet.has(c.value); });
}

function readFilterStateFromDom() {
    return {
        kindSet: getKindSetFromDom(),
        day: selectedDay || 'all',
        status: document.getElementById('filter-status')?.value || 'all',
        sort: document.getElementById('sort-by')?.value || 'date',
    };
}

function getFilteredSorted() {
    const status = document.getElementById('filter-status').value;
    const kindSet = getKindSetFromDom();
    const sort = document.getElementById('sort-by').value;
    let starts = (startsData.starts || []).slice();

    if (status !== 'all') starts = starts.filter(s => s.status === status);
    if (selectedDay) starts = starts.filter(s => localDay(s) === selectedDay);
    starts = starts.filter(s => kindSet.has(s.kind));

    starts.sort((a, b) => {
        if (sort === 'date') return a.start_time_unix - b.start_time_unix;
        if (sort === 'confidence') return (b.confidence || 0) - (a.confidence || 0);
        if (sort === 'start_confidence') return (b.start_confidence || 0) - (a.start_confidence || 0);
        if (sort === 'rounding_confidence') return (b.rounding_confidence || 0) - (a.rounding_confidence || 0);
        if (sort === 'review_priority') return reviewPriorityRank(b.review_priority) - reviewPriorityRank(a.review_priority);
        if (sort === 'wind') return (b.wind_speed_kts || 0) - (a.wind_speed_kts || 0);
        return a.start_time_unix - b.start_time_unix;
    });
    return starts;
}

function reviewPriorityRank(priority) {
    return {high: 3, medium: 2, low: 1}[priority] || 0;
}

function syncSelectionWithVisibleStarts(starts) {
    const visibleIds = new Set((starts || []).map((s) => s.id));
    if (selectedId && visibleIds.has(selectedId)) return false;
    const previous = (startsData.starts || []).find(s => s.id === selectedId);
    const previousDay = previous ? localDay(previous) : null;
    const sameDayStarts = previous
        ? (starts || []).filter(s => localDay(s) === previousDay) : [];
    const pool = sameDayStarts.length ? sameDayStarts : (starts || []);
    const newestVisible = (starts || []).reduce((best, s) => {
        if (!best || s.start_time_unix > best.start_time_unix) return s;
        return best;
    }, null);
    const newestInPool = pool.reduce((best, s) => {
        if (!best || s.start_time_unix > best.start_time_unix) return s;
        return best;
    }, null);
    const nextId = newestInPool ? newestInPool.id : (newestVisible ? newestVisible.id : null);
    const changed = nextId !== selectedId;
    selectedId = nextId;
    return changed;
}

function scrollSelectedCardIntoView() {
    if (!selectedId) return;
    const selectedCard = document.querySelector(`.start-card[data-id="${selectedId}"]`);
    if (selectedCard) selectedCard.scrollIntoView({block: 'nearest'});
}

function renderList(starts = null) {
    const container = document.getElementById('start-list');
    container.innerHTML = '';
    const visibleStarts = starts || getFilteredSorted();
    if (visibleStarts.length === 0) {
        container.innerHTML = '<div class="no-data" style="padding:20px;text-align:center">No events match the current filter.</div>';
        return;
    }
    for (const s of visibleStarts) container.appendChild(buildCard(s));
}

function buildCard(s) {
    s = {...s, status: reviewStatus(s.status)};
    const card = document.createElement('div');
    card.className = `start-card ${s.status}${s.id === selectedId ? ' selected' : ''}`;
    card.dataset.id = s.id;

    const wind = s.wind_speed_kts != null ? `${s.wind_speed_kts.toFixed(0)} kts` : '?';
    const windDir = s.wind_dir_deg != null ? `${s.wind_dir_deg.toFixed(0)}°` : '';
    const conf = s.confidence != null ? `${(s.confidence * 100).toFixed(0)}%` : '?';
    const startConf = s.start_confidence != null ? `${(s.start_confidence * 100).toFixed(0)}% start` : '? start';
    const roundConf = s.rounding_confidence != null ? `${(s.rounding_confidence * 100).toFixed(0)}% round` : '? round';
    const tacks = (s.tacks && s.tacks.length) ? s.tacks.length
        : (s.tack_count != null ? s.tack_count : '?');
    const gybes = (s.gybes && s.gybes.length) ? s.gybes.length
        : (s.gybe_count != null ? s.gybe_count : '?');
    const vmg = s.mean_vmg_kts != null ? s.mean_vmg_kts.toFixed(2) : '?';
    const accel = s.accel_time_s != null ? `${s.accel_time_s}s` : '?';
    const svgMap = buildMiniMap(s);

    card.innerHTML = `
    <div class="card-map">${svgMap}</div>
    <div class="card-info">
      <div class="card-date">${formatDate(s.start_time_unix)}</div>
      <div class="card-id">${utils.htmlEncode(s.id)}</div>
      <div class="card-badges">
        <span class="badge badge-${s.status}">${s.status}</span>
        <span class="badge badge-kind ${kindBadgeClass(s.kind)}">${kindLabel(s.kind)}</span>
        <span class="badge badge-wind">💨 ${wind} ${windDir}</span>
        <span class="badge badge-conf">⚡ ${conf}</span>
      </div>
      ${maneuverOrStartStats(s)}
      <div class="card-actions">
        <button class="card-btn card-btn-confirm ${s.status === 'confirmed' ? 'active' : ''}" title="Confirm">✓</button>
        <button class="card-btn card-btn-discard ${s.status === 'discarded' ? 'active' : ''}" title="Discard">✗</button>
      </div>
    </div>`;

    card.querySelector('.card-btn-confirm').addEventListener('click', e => {
        e.stopPropagation();
        setStatus(s.id, s.status === 'confirmed' ? 'pending' : 'confirmed');
    });
    card.querySelector('.card-btn-discard').addEventListener('click', e => {
        e.stopPropagation();
        setStatus(s.id, s.status === 'discarded' ? 'pending' : 'discarded');
    });
    card.addEventListener('click', () => selectStart(s.id));
    return card;
}

function maneuverOrStartStats(s) {
    const isManeuver = s.kind === 'tack' || s.kind === 'gybe';
    if (isManeuver) return maneuverStatsRow(s);
    return startStatsRow(s);
}

function startStatsRow(s) {
    const startConf = s.start_confidence != null ? `${(s.start_confidence * 100).toFixed(0)}% start` : '? start';
    const roundConf = s.rounding_confidence != null ? `${(s.rounding_confidence * 100).toFixed(0)}% round` : '? round';
    const tacks = (s.tacks && s.tacks.length) ? s.tacks.length
        : (s.tack_count != null ? s.tack_count : '?');
    const gybes = (s.gybes && s.gybes.length) ? s.gybes.length
        : (s.gybe_count != null ? s.gybe_count : '?');
    const vmg = s.mean_vmg_kts != null ? s.mean_vmg_kts.toFixed(2) : '?';
    const accel = s.accel_time_s != null ? `${s.accel_time_s}s` : '?';
    return `<div class="card-stats">
        <span>Start: <span class="val">${startConf}</span></span>
        <span>Round: <span class="val">${roundConf}</span></span>
        <span>T/G: <span class="val">${tacks}/${gybes}</span></span>
        <span>VMG: <span class="val">${vmg} kt</span></span>
        <span>Accel: <span class="val">${accel}</span></span>
      </div>`;
}

function fmtOrQ(v, digits = 1, suffix = '') {
    if (v == null || !Number.isFinite(v)) return '?';
    return `${Number(v).toFixed(digits)}${suffix}`;
}

function fmtSec(v) {
    if (v == null || !Number.isFinite(v)) return '?';
    return `${Number(v).toFixed(0)}s`;
}

function dirArrow(dir) {
    if (dir === 'P-to-S') return 'P→S';
    if (dir === 'S-to-P') return 'S→P';
    return '?';
}

function maneuverStatsRow(s) {
    const dHdg = s.hdg_change != null ? `${Math.round(Math.abs(s.hdg_change))}° ${dirArrow(s.direction)}` : '?';
    const entrySpd = fmtOrQ(s.entry_spd_kts, 2, ' kt');
    const minSpd = fmtOrQ(s.min_spd_kts, 2, ' kt');
    const r80 = fmtSec(s.spd_recovery_s_80);
    const r90 = fmtSec(s.spd_recovery_s_90);
    const below = fmtSec(s.time_below_80_spd_s);
    const lostM = fmtOrQ(s.distance_lost_m, 0, ' m');
    const lostS = fmtOrQ(s.time_lost_s, 0, ' s');
    const yaw = s.max_yaw_rate_deg_s != null ? `${Math.round(s.max_yaw_rate_deg_s)}°/s` : '?';
    const sym = s.twa_symmetry_deg != null
        ? `${s.twa_symmetry_deg > 0 ? '+' : ''}${Math.round(s.twa_symmetry_deg)}°`
        : '?';
    return `<div class="card-stats">
        <span>Δhdg: <span class="val">${dHdg}</span></span>
        <span>Entry spd: <span class="val">${entrySpd}</span></span>
        <span>Min spd: <span class="val">${minSpd}</span></span>
      </div>
      <div class="card-stats">
        <span>Spd ≥80%: <span class="val">${r80}</span></span>
        <span>≥90%: <span class="val">${r90}</span></span>
        <span>Below-80%: <span class="val">${below}</span></span>
      </div>
      <div class="card-stats">
        <span>Lost: <span class="val">${lostM} / ${lostS}</span></span>
        <span>Yaw: <span class="val">${yaw}</span></span>
        <span>TWA sym: <span class="val">${sym}</span></span>
      </div>`;
}

function buildMiniMap(s) {
    const track = s.track || [];
    if (track.length < 2) return '<text x="5" y="40" fill="#8b949e" font-size="10">no track</text>';

    const lats = track.map(p => p[0]);
    const lons = track.map(p => p[1]);
    const minLat = Math.min(...lats); const maxLat = Math.max(...lats);
    const minLon = Math.min(...lons); const maxLon = Math.max(...lons);
    const W = 90; const H = 70; const PAD = 5;

    const scaleX = (lon) => PAD + (lon - minLon) / (maxLon - minLon + 1e-10) * (W - 2 * PAD);
    const scaleY = (lat) => H - PAD - (lat - minLat) / (maxLat - minLat + 1e-10) * (H - 2 * PAD);

    const totalSecs = (s.first_beat_end_unix || s.window_end) - s.window_begin;
    const preStartSecs = s.start_time_unix - s.window_begin;
    const splitFrac = preStartSecs / (totalSecs + 1e-10);
    const splitIdx = Math.floor(track.length * splitFrac);

    const loiterPts = track.slice(0, splitIdx + 1);
    const beatPts = track.slice(splitIdx);

    function toPolyline(pts, color, width = 1.5) {
        if (pts.length < 2) return '';
        const d = pts.map((p, i) => `${i === 0 ? 'M' : 'L'}${scaleX(p[1]).toFixed(1)},${scaleY(p[0]).toFixed(1)}`).join(' ');
        return `<path d="${d}" stroke="${color}" stroke-width="${width}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`;
    }

    const sx = scaleX(track[splitIdx][1]).toFixed(1);
    const sy = scaleY(track[splitIdx][0]).toFixed(1);

    return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" style="background:#111820">
    ${toPolyline(loiterPts, '#8b949e')}
    ${toPolyline(beatPts, '#58a6ff', 2)}
    <circle cx="${sx}" cy="${sy}" r="3" fill="#f0a500"/>
  </svg>`;
}

// ---- Detail view ----------------------------------------------------------
function selectStart(id) {
    selectedId = id;
    document.querySelectorAll('.start-card').forEach(c => {
        c.classList.toggle('selected', c.dataset.id === id);
    });
    // Drop any pending scrubber-debounce write so a stale t from the prior
    // event cannot clobber the URL after we push the new event below.
    if (scrubUrlDebounceTimer) {
        clearTimeout(scrubUrlDebounceTimer);
        scrubUrlDebounceTimer = null;
    }
    // pushState so back/forward steps through distinct events. Reset t to 0
    // since each new event has its own scrubber axis (relative to its key time).
    pushUrl({event: id, t: 0});
    // Detail + per-session track load asynchronously. Render immediately with
    // whatever we have (preview track, top-level fields), then re-render once
    // either heavy payload arrives so charts / full session backdrop /
    // features populate. The selectedId guard avoids a stale render if the
    // user clicks past this start before its data finishes loading.
    renderDetail(id);
    const s = (startsData.starts || []).find(x => x.id === id);
    const sessionPromise = s ? ensureSession(s.file) : Promise.resolve(null);
    Promise.all([ensureDetail(id), sessionPromise]).then(([detail, session]) => {
        if (selectedId !== id) return;
        if (detail || session) renderDetail(id);
    });
}

function renderDetail(id) {
    const s = (startsData.starts || []).find(x => x.id === id);
    if (!s) return;

    document.getElementById('detail-empty').style.display = 'none';
    document.getElementById('detail-content').style.display = 'flex';

    document.getElementById('detail-title').textContent = formatDate(s.start_time_unix);
    const startText = s.start_confidence != null ? `start ${(s.start_confidence * 100).toFixed(0)}%` : 'start ?';
    const roundText = s.rounding_confidence != null ? `round ${(s.rounding_confidence * 100).toFixed(0)}%` : 'round ?';
    document.getElementById('detail-subtitle').textContent =
        `${s.id}  ·  ${kindLabel(s.kind)}  ·  ${startText}  ·  ${roundText}  ·  detector ${s.confidence != null ? (s.confidence * 100).toFixed(0) + '%' : '?'}  ·  ${s.file}`;

    const confirmBtn = document.getElementById('btn-confirm');
    const discardBtn = document.getElementById('btn-discard');
    confirmBtn.classList.toggle('active', s.status === 'confirmed');
    discardBtn.classList.toggle('active', s.status === 'discarded');
    confirmBtn.onclick = () => setStatus(id, s.status === 'confirmed' ? 'pending' : 'confirmed');
    discardBtn.onclick = () => setStatus(id, s.status === 'discarded' ? 'pending' : 'discarded');

    document.getElementById('detail-scrubber-range').value = 0;
    document.getElementById('detail-scrubber-time').textContent = '+0s';
    // Clear any stale inline display:none left from a prior selectStart run
    // (older builds toggled this on the fallback branch). The bar is now
    // always visible; the slider alone is disabled when there's no track.
    document.getElementById('detail-scrubber').style.display = '';

    renderDetailMap(s);
    requestAnimationFrame(() => renderCharts(s));
    updateVideoFrame(s);
    renderNotes(s);
    renderManeuversTable(s);
    renderStartComments(id);
}

function renderDetailMap(s) {
    if (!detailMap) {
        detailMap = L.map('detail-map', {
            zoomControl: true, attributionControl: true, keyboard: false,
            rotate: true, rotateControl: false, touchRotate: true,
        });
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '© OpenStreetMap contributors',
            maxZoom: 18,
        }).addTo(detailMap);
    }

    Object.values(detailMapLayers).forEach(l => l.remove());
    detailMapLayers = {};
    if (detailScrubberMarker) { detailScrubberMarker.remove(); detailScrubberMarker = null; }
    clearAisLayers();

    const fullTrackData = sessionCache.get(s.file) || null;
    const fullTrack = fullTrackData ? fullTrackData.track : null;

    if (fullTrack && fullTrack.length >= 2) {
        const startTime = s.start_time_unix;
        let startIdx = 0; let closestDiff = Infinity;
        fullTrack.forEach((p, idx) => {
            const diff = Math.abs(p[2] - startTime);
            if (diff < closestDiff) { closestDiff = diff; startIdx = idx; }
        });

        const allPts = fullTrack.map(p => [p[0], p[1]]);
        const preWindowStart = startTime - START_WINDOW_PRE_SEC;
        const postWindowEnd = startTime + START_WINDOW_POST_SEC;

        let preStartIdx = startIdx; let postEndIdx = startIdx;
        fullTrack.forEach((p, idx) => {
            if (p[2] >= preWindowStart && idx < startIdx) preStartIdx = Math.min(preStartIdx, idx);
            if (p[2] <= postWindowEnd && idx > startIdx) postEndIdx = Math.max(postEndIdx, idx);
        });

        const prePts = fullTrack.slice(preStartIdx, startIdx + 1).map(p => [p[0], p[1]]);
        const postPts = fullTrack.slice(startIdx, postEndIdx + 1).map(p => [p[0], p[1]]);

        detailMapLayers.fullTrack = L.polyline(allPts, {
            color: '#3b82f6', weight: 1.5, opacity: 0.4,
        }).addTo(detailMap);

        if (prePts.length >= 2) {
            detailMapLayers.preStart = L.polyline(prePts, {color: '#ef4444', weight: 3, opacity: 0.9}).addTo(detailMap);
        }
        if (postPts.length >= 2) {
            detailMapLayers.postStart = L.polyline(postPts, {color: '#22c55e', weight: 3, opacity: 0.9}).addTo(detailMap);
        }

        const startIcon = L.divIcon({
            html: `<div style="background:#f97316;width:14px;height:14px;border-radius:50%;border:3px solid #fff;box-shadow:0 0 6px rgba(0,0,0,0.5);"></div>`,
            className: '', iconAnchor: [7, 7],
        });
        detailMapLayers.startMark = L.marker([fullTrack[startIdx][0], fullTrack[startIdx][1]], {icon: startIcon}).addTo(detailMap);

        const avgTwd = getAvgTwd(s);
        if (avgTwd !== null) {
            const lineIdx = helperLineTrackIndex(s, fullTrack, startIdx);
            const startLat = fullTrack[lineIdx][0];
            const startLon = fullTrack[lineIdx][1];
            const arrowLen = 0.003;
            const windRad = avgTwd * Math.PI / 180;
            const tipLat = startLat + arrowLen * Math.cos(windRad);
            const tipLon = startLon + arrowLen * Math.sin(windRad) / Math.cos(startLat * Math.PI / 180);

            detailMapLayers.windArrow = L.polyline([[tipLat, tipLon], [startLat, startLon]], {
                color: '#00bfff', weight: 4, opacity: 0.9,
            }).addTo(detailMap);

            const headLen = arrowLen * 0.3;
            const headAngle = 25 * Math.PI / 180;
            const head1Rad = windRad + Math.PI - headAngle;
            const head2Rad = windRad + Math.PI + headAngle;
            const head1Lat = tipLat + headLen * Math.cos(head1Rad);
            const head1Lon = tipLon + headLen * Math.sin(head1Rad) / Math.cos(startLat * Math.PI / 180);
            const head2Lat = tipLat + headLen * Math.cos(head2Rad);
            const head2Lon = tipLon + headLen * Math.sin(head2Rad) / Math.cos(startLat * Math.PI / 180);

            detailMapLayers.windArrowHead1 = L.polyline([[tipLat, tipLon], [head1Lat, head1Lon]], {
                color: '#00bfff', weight: 4, opacity: 0.9,
            }).addTo(detailMap);
            detailMapLayers.windArrowHead2 = L.polyline([[tipLat, tipLon], [head2Lat, head2Lon]], {
                color: '#00bfff', weight: 4, opacity: 0.9,
            }).addTo(detailMap);

            const labelIcon = L.divIcon({
                html: `<div style="color:#fff;background:#0088cc;padding:2px 6px;border-radius:3px;font-size:14px;font-weight:bold;">TWD ${avgTwd.toFixed(0)}°</div>`,
                className: '', iconAnchor: [-10, 12],
            });
            detailMapLayers.windLabel = L.marker([tipLat, tipLon], {icon: labelIcon}).addTo(detailMap);

            const lineLen = 0.002;
            const lineRad = (avgTwd + 90) * Math.PI / 180;
            const line1Lat = startLat + lineLen * Math.cos(lineRad);
            const line1Lon = startLon + lineLen * Math.sin(lineRad) / Math.cos(startLat * Math.PI / 180);
            const line2Lat = startLat - lineLen * Math.cos(lineRad);
            const line2Lon = startLon - lineLen * Math.sin(lineRad) / Math.cos(startLat * Math.PI / 180);

            detailMapLayers.startLine = L.polyline([[line1Lat, line1Lon], [line2Lat, line2Lon]], {
                color: '#ffff00', weight: 3, opacity: 0.8, dashArray: '8, 4',
            }).addTo(detailMap);
        }

        detailFullTrack = fullTrack;
        const scrubber = document.getElementById('detail-scrubber-range');
        scrubber.min = -START_WINDOW_PRE_SEC;
        scrubber.max = START_WINDOW_POST_SEC;
        scrubber.step = 1;
        scrubber.value = 0;
        scrubber.disabled = false;
        updateDetailScrubberPosition(0);

        detailScrubberMarker = L.circleMarker([fullTrack[startIdx][0], fullTrack[startIdx][1]], {
            radius: 6, color: '#fff', fillColor: '#000', fillOpacity: 1, weight: 2,
        }).addTo(detailMap);

        detailMapLayers.fullTrack.on('click', (e) => {
            const closest = findClosestTrackPointDetail(e.latlng, fullTrack);
            const relTime = Math.round(fullTrack[closest][2] - s.start_time_unix);
            const clamped = Math.max(-START_WINDOW_PRE_SEC, Math.min(START_WINDOW_POST_SEC, relTime));
            scrubber.value = clamped;
            updateDetailScrubberPosition(clamped);
            document.getElementById('detail-scrubber-time').textContent = `${clamped >= 0 ? '+' : ''}${clamped}s`;
        });

        const gunLatLng = L.latLng(fullTrack[startIdx][0], fullTrack[startIdx][1]);
        const focusPts = fullTrack
            .filter(p => p[2] >= startTime - MAP_FOCUS_PRE_SEC
                         && p[2] <= startTime + MAP_FOCUS_POST_SEC)
            .map(p => [p[0], p[1]]);
        focusDetailMapOnEvent(focusPts.length >= 2 ? focusPts : [...prePts, ...postPts], gunLatLng, s);
    } else {
        // Fallback: windowed track from the start record
        const track = s.track || [];
        if (track.length < 2) return;

        const splitFrac = (s.start_time_unix - s.window_begin) / ((s.first_beat_end_unix || s.window_end) - s.window_begin + 1e-10);
        const splitIdx = Math.floor(track.length * splitFrac);
        const prePts = track.slice(0, splitIdx + 1).map(p => [p[0], p[1]]);
        const postPts = track.slice(splitIdx).map(p => [p[0], p[1]]);

        if (prePts.length >= 2) {
            detailMapLayers.preStart = L.polyline(prePts, {color: '#ef4444', weight: 3, opacity: 0.9}).addTo(detailMap);
        }
        if (postPts.length >= 2) {
            detailMapLayers.postStart = L.polyline(postPts, {color: '#22c55e', weight: 3, opacity: 0.9}).addTo(detailMap);
        }
        if (track[splitIdx]) {
            const startIcon = L.divIcon({
                html: `<div style="background:#f97316;width:14px;height:14px;border-radius:50%;border:3px solid #fff;"></div>`,
                className: '', iconAnchor: [7, 7],
            });
            detailMapLayers.startMark = L.marker([track[splitIdx][0], track[splitIdx][1]], {icon: startIcon}).addTo(detailMap);
        }

        // Fallback events have no full-track scrubber axis; disable the
        // slider but keep the chrome bar (play/skip/speed/mute/fullscreen)
        // visible so the user still has video controls.
        document.getElementById('detail-scrubber-range').disabled = true;
        const focusPts = track
            .filter(p => p[2] >= s.start_time_unix - MAP_FOCUS_PRE_SEC
                         && p[2] <= s.start_time_unix + MAP_FOCUS_POST_SEC)
            .map(p => [p[0], p[1]]);
        const eventPt = track[splitIdx] ? L.latLng(track[splitIdx][0], track[splitIdx][1]) : null;
        if (eventPt) focusDetailMapOnEvent(focusPts.length >= 2 ? focusPts : [...prePts, ...postPts], eventPt, s);
    }

    setTimeout(() => detailMap.invalidateSize(), 100);

    // Lazy-fetch the per-start AIS slice. Older starts (before AIS logging went
    // live) will return 404, which we handle quietly. The guard on id prevents a
    // stale fetch from painting when the user has moved on to another start.
    if (aisCurrentStartId !== s.id) {
        aisCurrentStartId = s.id;
        aisBoats = null;
        renderAisLegend();
        fetchJSON(`Analyze/AIS/${s.id}.json`)
            .then(data => {
                if (aisCurrentStartId !== s.id) return;
                aisBoats = (data && data.boats) || [];
                renderAisLegend();
                if (aisEnabled) updateAisLayer(currentScrubberValue());
            })
            .catch(() => {
                if (aisCurrentStartId === s.id) { aisBoats = []; renderAisLegend(); }
            });
    } else if (aisEnabled && aisBoats) {
        renderAisLegend();
        updateAisLayer(currentScrubberValue());
    }
}

function currentScrubberValue() {
    const scrub = document.getElementById('detail-scrubber-range');
    if (!scrub) return 0;
    const v = parseFloat(scrub.value);
    return Number.isFinite(v) ? v : 0;
}

function updateDetailScrubberPosition(relTime) {
    if (!detailFullTrack || !selectedId) return;
    const s = (startsData.starts || []).find(x => x.id === selectedId);
    if (!s) return;

    const targetTime = s.start_time_unix + relTime;
    let closestIdx = 0; let closestDiff = Infinity;
    detailFullTrack.forEach((p, idx) => {
        const diff = Math.abs(p[2] - targetTime);
        if (diff < closestDiff) { closestDiff = diff; closestIdx = idx; }
    });

    const pt = detailFullTrack[closestIdx];
    if (detailScrubberMarker && pt) detailScrubberMarker.setLatLng([pt[0], pt[1]]);
}

function helperLineTrackIndex(s, track, fallbackIdx) {
    // For starts, the line is the actual start line — anchor at gun position.
    if (s.kind === 'start') return fallbackIdx;
    const maneuver = (s.tacks && s.tacks[0]) || (s.gybes && s.gybes[0]) || null;
    const target = maneuver && Number.isFinite(maneuver.time_s)
        ? s.start_time_unix + maneuver.time_s : s.start_time_unix;
    let closestIdx = fallbackIdx;
    let closestDiff = Infinity;
    track.forEach((p, idx) => {
        const diff = Math.abs(p[2] - target);
        if (diff < closestDiff) { closestDiff = diff; closestIdx = idx; }
    });
    return closestIdx;
}

function focusDetailMapOnEvent(points, eventLatLng, s) {
    if (!detailMap || !points || points.length < 2 || !eventLatLng) return;
    requestAnimationFrame(() => {
        detailMap.invalidateSize();
        detailMap.fitBounds(L.latLngBounds(points).pad(0.12), {animate: false});
        applyMapRotation(s);

        requestAnimationFrame(() => {
            detailMap.invalidateSize();
            const size = detailMap.getSize();
            if (size.x <= 0 || size.y <= 0) return;
            const eventPx = detailMap.latLngToContainerPoint(eventLatLng);
            const targetPx = L.point(size.x / 2, size.y * MAP_EVENT_TOP_FRACTION);
            detailMap.panBy(eventPx.subtract(targetPx), {animate: false});
        });
    });
}

function findClosestTrackPointDetail(latlng, track) {
    let closest = 0; let minDist = Infinity;
    track.forEach((pt, idx) => {
        const dist = Math.pow(pt[0] - latlng.lat, 2) + Math.pow(pt[1] - latlng.lng, 2);
        if (dist < minDist) { minDist = dist; closest = idx; }
    });
    return closest;
}

function renderCharts(s) {
    charts = {};
    const tacks = s.tacks || [];

    function setupChart(canvasId, seriesData, opts) {
        const canvas = document.getElementById(canvasId);
        if (!canvas || !seriesData || seriesData.length < 2) return;

        const xs = seriesData.map(p => p[0]);
        const ys = seriesData.map(p => p[1]);
        const xMin = Math.min(...xs); const xMax = Math.max(...xs);
        const yMin = opts.yMin != null ? opts.yMin : Math.min(...ys);
        const yMax = opts.yMax != null ? opts.yMax : Math.max(...ys);

        charts[canvasId] = {canvas, seriesData, opts, xMin, xMax, yMin, yMax};

        canvas.onclick = (e) => {
            const chart = charts[canvasId];
            if (!chart) return;
            const rect = canvas.getBoundingClientRect();
            const W = canvas.width;
            const PAD = {left: 36, right: 8};
            const plotW = W - PAD.left - PAD.right;
            const px = (e.clientX - rect.left) * (W / rect.width);
            const t = chart.xMin + (px - PAD.left) / plotW * (chart.xMax - chart.xMin);
            const clamped = Math.max(-START_WINDOW_PRE_SEC, Math.min(START_WINDOW_POST_SEC, Math.round(t)));
            const scrubber = document.getElementById('detail-scrubber-range');
            scrubber.value = clamped;
            onDetailScrub();
        };

        drawChart(canvasId, 0);
    }

    if (s.awa_series) setupChart('chart-awa', s.awa_series, {
        color: '#f97316', height: 90, yMin: -180, yMax: 180, ylabel: 'AWA (°)', tacks, decimals: 0,
        thresholds: [40, -40], unit: '°',
    });
    if (s.hdg_series) setupChart('chart-hdg', s.hdg_series, {
        color: '#a855f7', height: 90, yMin: 0, yMax: 360, ylabel: 'HDG (°)', tacks, decimals: 0, unit: '°',
    });
    if (s.speed_series) setupChart('chart-speed', s.speed_series, {
        color: '#58a6ff', height: 90, yMin: 0, ylabel: 'spd (kt)', tacks, decimals: 1, unit: 'kt',
    });
    if (s.vmg_series) setupChart('chart-vmg', s.vmg_series, {
        color: '#3fb950', height: 90, ylabel: 'VMG (kt)', tacks, decimals: 1, unit: 'kt',
    });
    if (s.twd_series) setupChart('chart-twd', s.twd_series, {
        color: '#f472b6', height: 90, yMin: 0, yMax: 360, ylabel: 'TWD (°)', tacks, decimals: 0, unit: '°',
    });
}

function drawChart(canvasId, cursorTime) {
    const chart = charts[canvasId];
    if (!chart) return;
    const {canvas, seriesData, opts, xMin, xMax, yMin, yMax} = chart;
    const ctx = canvas.getContext('2d');

    canvas.width = canvas.parentElement.clientWidth - 24;
    canvas.height = opts.height || 90;
    const W = canvas.width; const H = canvas.height;
    const PAD = {left: 36, right: 8, top: 8, bottom: 20};
    const plotW = W - PAD.left - PAD.right;
    const plotH = H - PAD.top - PAD.bottom;

    const sx = x => PAD.left + (x - xMin) / (xMax - xMin + 1e-10) * plotW;
    const sy = y => PAD.top + (1 - (y - yMin) / (yMax - yMin + 1e-10)) * plotH;

    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#161b22';
    ctx.fillRect(0, 0, W, H);

    ctx.strokeStyle = '#21262d';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 3; i++) {
        const y = yMin + i * (yMax - yMin) / 3;
        const py = sy(y);
        ctx.beginPath();
        ctx.moveTo(PAD.left, py);
        ctx.lineTo(W - PAD.right, py);
        ctx.stroke();
        ctx.fillStyle = '#8b949e';
        ctx.font = '10px sans-serif';
        ctx.textAlign = 'right';
        ctx.fillText(y.toFixed(opts.decimals != null ? opts.decimals : 1), PAD.left - 3, py + 3);
    }

    if (yMin < 0 && yMax > 0) {
        ctx.strokeStyle = '#30363d';
        ctx.beginPath();
        ctx.moveTo(PAD.left, sy(0));
        ctx.lineTo(W - PAD.right, sy(0));
        ctx.stroke();
    }

    if (opts.thresholds) {
        ctx.strokeStyle = '#22c55e';
        ctx.setLineDash([4, 4]);
        opts.thresholds.forEach(th => {
            if (th >= yMin && th <= yMax) {
                ctx.beginPath();
                ctx.moveTo(PAD.left, sy(th));
                ctx.lineTo(W - PAD.right, sy(th));
                ctx.stroke();
            }
        });
        ctx.setLineDash([]);
    }

    ctx.strokeStyle = '#f0a500';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(sx(0), PAD.top);
    ctx.lineTo(sx(0), H - PAD.bottom);
    ctx.stroke();
    ctx.setLineDash([]);

    if (opts.tacks) {
        opts.tacks.forEach(t => {
            ctx.strokeStyle = t.time_s < 0 ? '#555' : '#3fb950';
            ctx.lineWidth = 1;
            ctx.setLineDash([3, 3]);
            ctx.beginPath();
            ctx.moveTo(sx(t.time_s), PAD.top);
            ctx.lineTo(sx(t.time_s), H - PAD.bottom);
            ctx.stroke();
            ctx.setLineDash([]);
        });
    }

    ctx.strokeStyle = opts.color || '#58a6ff';
    ctx.lineWidth = 2;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    seriesData.forEach((p, i) => {
        const px = sx(p[0]); const py = sy(p[1]);
        i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
    });
    ctx.stroke();

    ctx.fillStyle = '#8b949e';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    for (let i = 0; i <= 5; i++) {
        const xv = xMin + i * (xMax - xMin) / 5;
        ctx.fillText(`${xv.toFixed(0)}s`, sx(xv), H - 4);
    }

    if (cursorTime >= xMin && cursorTime <= xMax) {
        const cx = sx(cursorTime);
        ctx.strokeStyle = '#ff0000';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(cx, PAD.top);
        ctx.lineTo(cx, H - PAD.bottom);
        ctx.stroke();

        let val = null;
        for (let i = 0; i < seriesData.length - 1; i++) {
            if (seriesData[i][0] <= cursorTime && seriesData[i + 1][0] >= cursorTime) {
                const t0 = seriesData[i][0]; const t1 = seriesData[i + 1][0];
                const v0 = seriesData[i][1]; const v1 = seriesData[i + 1][1];
                val = v0 + (v1 - v0) * (cursorTime - t0) / (t1 - t0 + 1e-10);
                break;
            }
        }
        if (val != null) {
            const cy = sy(val);
            ctx.fillStyle = '#ff0000';
            ctx.beginPath();
            ctx.arc(cx, cy, 3, 0, 2 * Math.PI);
            ctx.fill();

            const label = `${val.toFixed(opts.decimals != null ? opts.decimals : 1)}${opts.unit || ''}`;
            ctx.font = 'bold 11px sans-serif';
            ctx.textAlign = 'right';
            const textW = ctx.measureText(label).width;
            ctx.fillStyle = 'rgba(0,0,0,0.7)';
            ctx.fillRect(W - PAD.right - textW - 6, PAD.top, textW + 6, 14);
            ctx.fillStyle = '#ff5555';
            ctx.fillText(label, W - PAD.right - 3, PAD.top + 11);
        }
    }
}

function redrawChartsWithCursor(cursorTime) {
    Object.keys(charts).forEach(id => drawChart(id, cursorTime));
}

function renderNotes(s) {
    const ta = document.getElementById('detail-notes');
    ta.value = s.notes || '';
    ta.classList.remove('saved');

    const fresh = ta.cloneNode(true);
    fresh.value = s.notes || '';
    ta.parentNode.replaceChild(fresh, ta);

    let saveTimer = null;
    fresh.addEventListener('input', () => {
        fresh.classList.remove('saved');
        clearTimeout(saveTimer);
        saveTimer = setTimeout(() => commitNotes(s, fresh), 1500);
    });
    fresh.addEventListener('blur', () => {
        clearTimeout(saveTimer);
        commitNotes(s, fresh);
    });
}

function commitNotes(s, ta) {
    const newVal = ta.value;
    if (newVal === (s.notes || '')) return;
    s.notes = newVal;
    upsertEdit(s.id, {notes: newVal});
    document.getElementById('save-btn').disabled = false;

    saveData({silent: true}).then(() => {
        ta.classList.add('saved');
        setTimeout(() => ta.classList.remove('saved'), 1500);
    });
}

// ---- Video integration ----------------------------------------------------
// Same-origin: viewer360 module is bundled, shared.signAWSUrl reads the
// sailview cookies directly.
let viewer = null;
let videosJson = null;
let videosColumnsMap = null;
let currentVideoBasename = null;
let currentVideoRecord = null;
let videosFetching = false;
let pendingSeekForStart = null;
let pendingSeekBasename = null;

// Clip chaining: when a clip ends mid-review-window, automatically load next.
const CLIP_GAP_SECONDS = 15; // typical gap between Insta360 clips

function normalizeCreateDate(cd) {
    return (cd && cd.length >= 19)
        ? cd.slice(0, 10).replace(/[/:]/g, '-') + cd.slice(10, 19) : '';
}

function showVideoMessage(html) {
    const msg = document.getElementById('video-message');
    if (!msg) return;
    msg.innerHTML = html;
    msg.style.display = 'flex';
    const mount = document.getElementById('viewer-mount');
    if (mount) mount.style.display = 'none';
}

function hideVideoMessage() {
    const msg = document.getElementById('video-message');
    if (msg) msg.style.display = 'none';
    const mount = document.getElementById('viewer-mount');
    if (mount) mount.style.display = '';
}

/**
 * Find the video clip immediately after `currentRecord` in chronological order.
 * Returns null if there's no next clip or if the gap is too large (>60s).
 */
function findNextVideoClip(currentRecord) {
    if (!videosJson || !videosJson.videos || !currentRecord) return null;

    const currentKey = normalizeCreateDate(currentRecord.CreateDate);
    if (!currentKey) return null;

    const candidates = [];
    for (const v of videosJson.videos) {
        const key = normalizeCreateDate(v.CreateDate);
        if (key && key > currentKey) {
            candidates.push({v, key});
        }
    }
    candidates.sort((a, b) => a.key.localeCompare(b.key));

    if (candidates.length === 0) return null;

    const next = candidates[0];
    const currentDate = new Date(currentKey.replace(' ', 'T') + 'Z');
    const nextDate = new Date(next.key.replace(' ', 'T') + 'Z');
    const gapMs = nextDate - currentDate;

    // Typical clip is ~29 min (1740s), with 15s gap. If gap > 60s, it's a
    // different session or day — don't auto-chain.
    const expectedClipDuration = 29 * 60 * 1000;
    const maxGap = expectedClipDuration + 60 * 1000;
    if (gapMs > maxGap) {
        console.log(`[review] next clip gap ${(gapMs/1000).toFixed(0)}s too large, not chaining`);
        return null;
    }

    console.log(`[review] found next clip: ${next.v.basename} (gap ${(gapMs/1000).toFixed(0)}s)`);
    return next.v;
}

function ensureVideosJson(cb) {
    if (videosJson) { cb(null); return; }
    if (videosFetching) return;
    videosFetching = true;

    const url = shared.signAWSUrl('Insta360/videos.json');
    if (!url) {
        videosFetching = false;
        cb(new Error('Could not sign videos.json URL'));
        return;
    }

    utils.getJSON(url, (err, data) => {
        videosFetching = false;
        if (err || !data) {
            cb(err || new Error('Empty videos.json'));
            return;
        }
        videosJson = data;
        // Derive basename for each video the same way sailview does.
        (videosJson.videos || []).forEach((v) => {
            if (!v.basename && v.SourceFile) {
                const [basename] = utils.filenameSplit(v.SourceFile);
                v.basename = basename;
            }
        });
        videosColumnsMap = {};
        if (videosJson.columns) {
            for (const [name, idx] of Object.entries(videosJson.columns)) {
                videosColumnsMap[idx] = name;
            }
        }
        cb(null);
    });
}

// ---- Instrument overlay ---------------------------------------------------
function cacheOverlayRows() {
    if (overlayRows) return overlayRows;
    const map = {};
    document.querySelectorAll('#video-overlay .ov-data').forEach((row) => {
        const ch = row.getAttribute('data-channel');
        map[ch] = {
            row,
            val: row.querySelector('.ov-value'),
            spark: row.querySelector('.ov-sparkline'),
        };
    });
    overlayRows = map;
    overlayMapSvg = document.getElementById('overlay-map');
    return overlayRows;
}

function resetOverlay() {
    overlayBoatView = null;
    overlayBasename = null;
    overlayFrame = null;
    cacheOverlayRows();
    Object.values(overlayRows || {}).forEach((r) => {
        r.val.textContent = '--';
        while (r.spark.firstChild) r.spark.removeChild(r.spark.firstChild);
    });
    if (overlayMapSvg) {
        while (overlayMapSvg.firstChild) overlayMapSvg.removeChild(overlayMapSvg.firstChild);
    }
}

function getReviewWindowTrack(s) {
    const fullTrackData = sessionCache.get(s.file) || null;
    const fullTrack = fullTrackData ? fullTrackData.track : null;
    const fullTrackM = fullTrackData ? fullTrackData.track_m : null;

    if (fullTrackM && fullTrackM.length >= 2) {
        const startTime = s.start_time_unix;
        let startIdx = 0;
        let closestDiff = Infinity;
        fullTrackM.forEach((p, idx) => {
            const diff = Math.abs(p[2] - startTime);
            if (diff < closestDiff) {
                closestDiff = diff;
                startIdx = idx;
            }
        });

        const preWindowStart = startTime - START_WINDOW_PRE_SEC;
        const postWindowEnd = startTime + START_WINDOW_POST_SEC;
        let preStartIdx = startIdx;
        let postEndIdx = startIdx;
        fullTrackM.forEach((p, idx) => {
            if (p[2] >= preWindowStart && idx < startIdx) preStartIdx = Math.min(preStartIdx, idx);
            if (p[2] <= postWindowEnd && idx > startIdx) postEndIdx = Math.max(postEndIdx, idx);
        });

        const windowTrack = fullTrackM.slice(preStartIdx, postEndIdx + 1);
        return {
            startPoint: fullTrackM[startIdx],
            startWindowIdx: startIdx - preStartIdx,
            windowTrack,
            y: windowTrack.map(p => p[0]),
            x: windowTrack.map(p => p[1]),
        };
    }

    // Event detail can also carry an already-windowed projected track.
    if (s.track_m && s.track_m.length >= 2) {
        const totalSecs = (s.first_beat_end_unix || s.window_end) - s.window_begin;
        const preStartSecs = s.start_time_unix - s.window_begin;
        const splitFrac = preStartSecs / (totalSecs + 1e-10);
        const startIdx = Math.max(0, Math.min(s.track_m.length - 1, Math.floor(s.track_m.length * splitFrac)));
        return {
            startPoint: s.track_m[startIdx],
            startWindowIdx: startIdx,
            windowTrack: s.track_m,
            y: s.track_m.map(p => p[0]),
            x: s.track_m.map(p => p[1]),
        };
    }

    if (!fullTrack || fullTrack.length < 2) return null;

    const startTime = s.start_time_unix;
    let startIdx = 0;
    let closestDiff = Infinity;
    fullTrack.forEach((p, idx) => {
        const diff = Math.abs(p[2] - startTime);
        if (diff < closestDiff) {
            closestDiff = diff;
            startIdx = idx;
        }
    });

    const preWindowStart = startTime - START_WINDOW_PRE_SEC;
    const postWindowEnd = startTime + START_WINDOW_POST_SEC;
    let preStartIdx = startIdx;
    let postEndIdx = startIdx;
    fullTrack.forEach((p, idx) => {
        if (p[2] >= preWindowStart && idx < startIdx) preStartIdx = Math.min(preStartIdx, idx);
        if (p[2] <= postWindowEnd && idx > startIdx) postEndIdx = Math.max(postEndIdx, idx);
    });

    const windowTrack = fullTrack.slice(preStartIdx, postEndIdx + 1);
    return {
        startPoint: fullTrack[startIdx],
        startWindowIdx: startIdx - preStartIdx,
        windowTrack,
        y: windowTrack.map(p => p[0]),
        x: windowTrack.map(p => p[1]),
    };
}

// Overlay frame constants
const OVERLAY_MIN_HALF_WIDTH_M = 20;   // Minimum half-width in meters
const OVERLAY_PADDING_FACTOR = 1.08;   // 8% padding around track bounds
const OVERLAY_VERTICAL_OFFSET = 0.3;   // Start line at 30% from bottom of viewport

/**
 * Build a wind-relative coordinate frame for the overlay mini-map.
 *
 * The transformation rotates the track so that the wind direction points
 * upward (negative Y in screen space after the SVG y-flip). The origin is
 * placed at the start position, so x=0 represents the start line perpendicular
 * to wind.
 *
 * Coordinate system:
 *   - Input: (y, x) in projected meters where y ~ north, x ~ east
 *   - Output: (y, x) in wind-relative frame where +y is downwind, +x is
 *     perpendicular to wind (starboard side when facing upwind)
 *
 * The rotation formula for angle θ (windDeg in radians):
 *   x' = dx·cos(θ) - dy·sin(θ)
 *   y' = dx·sin(θ) + dy·cos(θ)
 *
 * This rotates the coordinate system clockwise by windDeg, which makes the
 * wind direction (compass bearing) point along the +y axis.
 */
function makeOverlayFrame(reviewTrack, windDeg) {
    if (!reviewTrack || windDeg == null || !isFinite(windDeg)) return null;
    const startY = reviewTrack.startPoint[0];
    const startX = reviewTrack.startPoint[1];
    const rad = windDeg * Math.PI / 180;
    const sin = Math.sin(rad);
    const cos = Math.cos(rad);

    const toLocal = (y, x) => {
        const dx = x - startX;
        const dy = y - startY;
        return {
            x: dx * cos - dy * sin,
            y: dx * sin + dy * cos,
        };
    };

    const localPts = reviewTrack.windowTrack.map((p) => toLocal(p[0], p[1]));
    const prePts = localPts.slice(0, (reviewTrack.startWindowIdx || 0) + 1);
    const xs = prePts.map((p) => p.x);
    const minX = xs.length ? Math.min(...xs) : 0;
    const maxX = xs.length ? Math.max(...xs) : 0;
    // Width measured from the start line (x=0) - must include both the start
    // point AND all pre-start positions. halfWidth is the max distance from
    // the line to any pre-start point on either side.
    const halfWidth = Math.max(Math.abs(minX), Math.abs(maxX), OVERLAY_MIN_HALF_WIDTH_M);
    const boxSize = halfWidth * 2 * OVERLAY_PADDING_FACTOR;

    return {
        toLocal,
        boxSize,
        // Position viewBox so start line (y=0) sits at OVERLAY_VERTICAL_OFFSET from bottom
        viewBox: [-boxSize / 2, -OVERLAY_VERTICAL_OFFSET * boxSize, boxSize, boxSize],
        x: localPts.map((p) => p.x),
        y: localPts.map((p) => p.y),
    };
}

function toOverlayHeading(heading, windDeg) {
    if (heading == null || !isFinite(heading)) return heading;
    if (windDeg == null || !isFinite(windDeg)) return heading;
    return ((heading - windDeg) % 360 + 360) % 360;
}

// Build the BoatView once the log is loaded. Safe to call repeatedly — it
// bails out if the boatView is already built for the current clip or the log
// columns aren't ready yet.
function tryInitOverlayBoatView(s) {
    if (!viewer) return;
    if (overlayBoatView && overlayBasename === currentVideoBasename) return;
    const lat = viewer.getLogColumn('map_lat');
    const lon = viewer.getLogColumn('map_lon');
    const hdg = viewer.getLogColumn('hdg');
    if (!lat || !lon || !hdg) return;

    cacheOverlayRows();
    if (!overlayMapSvg) return;
    while (overlayMapSvg.firstChild) overlayMapSvg.removeChild(overlayMapSvg.firstChild);

    // Build the overlay track from the same race-window data as the Leaflet
    // detail map, not from the current video clip log.
    const range = viewer.getUnixRange();
    const startUnix = s.start_time_unix * 1000;
    const reviewTrack = getReviewWindowTrack(s);
    const avgTwd = getAvgTwd(s);
    overlayFrame = makeOverlayFrame(reviewTrack, avgTwd);
    const lat0 = overlayFrame ? overlayFrame.y : (reviewTrack ? reviewTrack.y : lat);
    const lon0 = overlayFrame ? overlayFrame.x : (reviewTrack ? reviewTrack.x : lon);
    const hdg0 = hdg;
    overlayBoatView = new sparkline.BoatView(overlayMapSvg, lat0, lon0, hdg0, {
        fixedViewport: true,
        boatScale: 2.8,
        // Wind-up scene: `toOverlayHeading(hd, avgTwd)` has already rotated
        // the heading into a wind-relative angle before BoatView.update is
        // called. No magnetic→true correction should be applied on top.
        // (Pre-Stage-4, BoatView unconditionally added +15.4°, which
        // double-rotated the boat glyph by the Seattle declination.)
        absoluteFrame: false,
    });
    overlayBasename = currentVideoBasename;

    // Seed the overlay once at the start gun if it falls inside this clip.
    // The mini-map is meant to be a fixed start-context widget, not a
    // live-following map while the video plays.
    if (range && startUnix >= range[0] && startUnix <= range[1]) {
        const tMs = startUnix - range[0];
        const la = reviewTrack ? reviewTrack.startPoint[0] : viewer.getLog(tMs, 'map_lat');
        const lo = reviewTrack ? reviewTrack.startPoint[1] : viewer.getLog(tMs, 'map_lon');
        const hd = viewer.getLog(tMs, 'hdg');
        if (la != null && lo != null && hd != null) {
            if (overlayFrame) {
                const p = overlayFrame.toLocal(la, lo);
                overlayBoatView.update(p.y, p.x, toOverlayHeading(hd, avgTwd));
                overlayBoatView.setViewBox(...overlayFrame.viewBox, overlayFrame.boxSize / 55);
                overlayBoatView.start(0);
            } else {
                overlayBoatView.update(la, lo, hd);
                overlayBoatView.start(avgTwd || 0);
            }
        }
    }
    overlayBoatView.setWindUp(null);
}

function updateOverlay(timeMs, s) {
    if (!viewer) return;
    cacheOverlayRows();

    for (const {channel, unit, decimals} of OVERLAY_FIELDS) {
        const r = overlayRows[channel];
        if (!r) continue;
        const val = viewer.getLog(timeMs, channel);
        if (val == null || isNaN(val)) {
            r.val.textContent = '--';
            continue;
        }
        r.val.textContent = `${val.toFixed(decimals)}${unit}`;
        const hist = viewer.getLogHistory(timeMs, channel, OVERLAY_SPARK_WINDOW_MS);
        if (hist && hist.length > 1) sparkline.sparkline(r.spark, hist);
    }

    tryInitOverlayBoatView(s);

    // Keep the overlay map itself fixed; only move the tiny boat glyph to the
    // current playback position, mirroring Sailview's mini-map behavior.
    if (overlayBoatView) {
        const la = viewer.getLog(timeMs, 'map_lat');
        const lo = viewer.getLog(timeMs, 'map_lon');
        const hd = viewer.getLog(timeMs, 'hdg');
        if (la != null && lo != null && hd != null) {
            if (overlayFrame) {
                const p = overlayFrame.toLocal(la, lo);
                overlayBoatView.update(p.y, p.x, toOverlayHeading(hd, getAvgTwd(s)));
            } else {
                overlayBoatView.update(la, lo, hd);
            }
        }
    }
}

function ensureViewer() {
    if (viewer) return viewer;
    viewer = viewer360.create(document.getElementById('viewer-mount'), {
        keyboard: true,
        stabilize: true,
    });

    // viewer360 creates the <video> element with muted=true so autoplay can't
    // be blocked by browser policy. Review prefers sound on by default — if
    // unmuted autoplay is refused (no MEI / no prior gesture) viewer360's
    // loadVideo falls back to muted playback; user presses M to unmute.
    viewer.video.muted = false;

    // Make the canvas non-focusable to prevent it from capturing keyboard events
    // when clicked. Our window-level handler will still work.
    if (viewer.canvas) {
        viewer.canvas.tabIndex = -1;
    }

    // When the video is playing, its currentTime drives the scrubber / map /
    // charts. We throttle to avoid redrawing on every frame; ~10 Hz is plenty.
    let lastTick = 0;
    let loggedOnce = false;
    viewer.video.addEventListener('timeupdate', () => {
        if (!selectedId) return;
        const now = performance.now();
        if (now - lastTick < 100) return;
        lastTick = now;

        const s = (startsData.starts || []).find(x => x.id === selectedId);
        if (!s) return;

        const ct = viewer.video.currentTime;
        const unixMs = viewer.getUnixAtVideoMs(ct * 1000);
        if (unixMs == null || !isFinite(unixMs)) {
            if (!loggedOnce) {
                console.warn('[review] timeupdate: getLog(row_times) returned', unixMs,
                             'currentTime=', ct);
                loggedOnce = true;
            }
            return;
        }

        const relTime = Math.round((unixMs - s.start_time_unix * 1000) / 1000);
        const clamped = Math.max(-START_WINDOW_PRE_SEC, Math.min(START_WINDOW_POST_SEC, relTime));
        if (!loggedOnce) {
            console.log('[review] timeupdate firing; ct=', ct.toFixed(2),
                        'unixMs=', unixMs, 'rel=', relTime);
            loggedOnce = true;
        }
        const scrubber = document.getElementById('detail-scrubber-range');
        if (String(scrubber.value) !== String(clamped)) {
            scrubber.value = clamped;
        }
        applyScrubberUI(clamped);
        updateOverlay(ct * 1000, s);
    });

    // Keep the play button label in sync with the actual playback state.
    // Listen to the broader event set so transient states (buffering, seeking,
    // play() rejected mid-load) can't leave the icon stuck — `play`/`pause`
    // alone miss those cases.
    ['play', 'playing', 'pause', 'seeking', 'seeked', 'waiting', 'ended', 'emptied']
        .forEach((ev) => viewer.video.addEventListener(ev, syncPlayBtn));
    syncChromeBar();

    // Clip chaining: when current clip ends, check if we're still within the
    // review window and load the next clip if available.
    viewer.video.addEventListener('ended', () => {
        if (!selectedId || !currentVideoRecord) return;
        const s = (startsData.starts || []).find(x => x.id === selectedId);
        if (!s) return;

        // Figure out where we are relative to the start gun
        const clipEndUnixMs = viewer.getUnixAtVideoMs(viewer.video.duration * 1000);
        if (clipEndUnixMs == null) return;

        const relTimeSec = (clipEndUnixMs - s.start_time_unix * 1000) / 1000;
        console.log(`[review] clip ended at rel=${relTimeSec.toFixed(0)}s`);

        // Only chain if we're still within the review window
        if (relTimeSec >= START_WINDOW_POST_SEC) {
            console.log('[review] past review window, not chaining');
            return;
        }

        const nextClip = findNextVideoClip(currentVideoRecord);
        if (!nextClip) {
            console.log('[review] no next clip available');
            return;
        }

        console.log(`[review] chaining to next clip: ${nextClip.basename}`);

        // Show a brief message during the transition (covers the ~15s gap)
        showVideoMessage(`Loading next clip...<br><small>~${CLIP_GAP_SECONDS}s gap between recordings</small>`);

        loadVideoClip(nextClip);

        // Wait for the new clip to load, then seek to the start and play
        const onLoaded = () => {
            viewer.video.removeEventListener('loadedmetadata', onLoaded);
            hideVideoMessage();
            // The new clip starts at its own time=0, which corresponds to its
            // CreateDate. Seek to the beginning and resume playback.
            viewer.video.currentTime = 0;
            viewer.video.play().catch(e => console.warn('[review] auto-play failed:', e));
        };
        viewer.video.addEventListener('loadedmetadata', onLoaded);
    });

    return viewer;
}

function togglePlay() {
    if (!viewer) return;
    const v = viewer.video;
    if (v.paused || v.ended) {
        v.play().catch(e => {
            console.warn('[review] play() rejected', e);
            syncPlayBtn();
        });
    } else {
        v.pause();
    }
    // Optimistic update so the icon flips on click rather than waiting for
    // the play/playing event (which can be delayed by buffering or never
    // fire if play() rejects).
    syncPlayBtn();
}

// Module-scope so togglePlay and the keyboard handler can call it directly.
function syncPlayBtn() {
    const btn = document.getElementById('detail-play-btn');
    if (!btn || !viewer) return;
    btn.textContent = (viewer.video.paused || viewer.video.ended) ? '▶' : '❚❚';
}

// Discrete cycle for the chrome speed button. The 's'/'d' keys still do
// fine-grained ±10% multiplier (useful for slow-mo at the gun); the button
// snaps to the canonical sailview speeds.
const CHROME_SPEEDS = [1, 1.5, 2, 4];

function formatRate(r) {
    return (r === Math.round(r) ? r.toFixed(0) : r.toFixed(2).replace(/\.?0+$/, '')) + '×';
}

function wireChromeBar() {
    document.getElementById('detail-skip-back').addEventListener('click', () => {
        if (!viewer) return;
        viewer.video.currentTime = Math.max(0, viewer.video.currentTime - 5);
    });
    document.getElementById('detail-skip-fwd').addEventListener('click', () => {
        if (!viewer) return;
        viewer.video.currentTime = Math.min(
            viewer.video.duration || Infinity,
            viewer.video.currentTime + 5
        );
    });
    document.getElementById('detail-speed-btn').addEventListener('click', () => {
        if (!viewer) return;
        const cur = viewer.video.playbackRate;
        const next = CHROME_SPEEDS.find(s => s > cur + 1e-3) || CHROME_SPEEDS[0];
        viewer.video.playbackRate = next;
    });
    document.getElementById('detail-mute-btn').addEventListener('click', () => {
        if (!viewer) return;
        viewer.video.muted = !viewer.video.muted;
    });
    document.getElementById('detail-fullscreen-btn').addEventListener('click', () => {
        const target = document.getElementById('video-container');
        const exit = document.exitFullscreen
            || document.webkitExitFullscreen
            || document.webkitCancelFullScreen;
        const enter = target && (target.requestFullscreen
            || target.webkitRequestFullscreen
            || target.webkitRequestFullScreen);
        const inFs = document.fullscreenElement || document.webkitFullscreenElement;
        if (inFs) { if (exit) exit.call(document); }
        else if (enter) enter.call(target);
    });
}

// Called from setupViewer once the <video> exists. Keeps the speed and mute
// labels honest when those state changes happen via keyboard, OS controls,
// or autoplay.
function syncChromeBar() {
    if (!viewer) return;
    const v = viewer.video;
    const speedBtn = document.getElementById('detail-speed-btn');
    const muteBtn = document.getElementById('detail-mute-btn');
    const update = () => {
        if (speedBtn) speedBtn.textContent = formatRate(v.playbackRate);
        if (muteBtn) {
            muteBtn.textContent = v.muted ? '🔇' : '🔊';
            muteBtn.classList.toggle('muted', v.muted);
        }
    };
    v.addEventListener('ratechange', update);
    v.addEventListener('volumechange', update);
    update();
}

function updateVideoFrame(s) {
    ensureVideosJson((err) => {
        if (err) {
            showVideoMessage(`Could not load videos.json: ${err.message || err}`);
            return;
        }

        const unixMs = s.start_time_unix * 1000;
        const targetIso = new Date(unixMs).toISOString();
        const targetPacific = viewer360.wallClockInTz(unixMs, 'America/Los_Angeles');
        const targetDay = targetPacific.slice(0, 10);
        console.log(`[review] start ${s.id}: unix=${s.start_time_unix} -> UTC ${targetIso} / Pacific ${targetPacific}`);

        const sameDay = (videosJson.videos || [])
            .filter(v => normalizeCreateDate(v.CreateDate).slice(0, 10) === targetDay);
        console.log(`[review] videos.json has ${(videosJson.videos || []).length} videos total; ` +
                    `${sameDay.length} on Pacific day ${targetDay}:`,
            sameDay.map(v => `${v.CreateDate}  (${v.basename || v.SourceFile})  log=${v.LogFile || '-'}`));

        const record = viewer360.pickVideoForUnix(videosJson.videos, unixMs);
        if (!record) {
            console.warn(`[review] pickVideoForUnix returned null for ${s.id} (target ${targetPacific})`);
            showVideoMessage(`No video available for ${s.date} (Pacific ${targetDay}).\n` +
                             `videos.json has ${sameDay.length} video(s) for that day — see console.`);
            return;
        }
        console.log(`[review] picked: ${record.basename} CreateDate=${record.CreateDate} Log=${record.LogFile}`);
        hideVideoMessage();
        ensureViewer();

        if (record.basename !== currentVideoBasename) {
            loadVideoClip(record, unixMs);
        }

        syncVideoToScrubber(s, 0);
    });
}

/**
 * Load a specific video clip into the viewer.
 */
function loadVideoClip(record, targetUnixMs = null) {
    if (!viewer || !record) return;
    const videoKey = videoKeyForRecord(record);
    if (!videoKey) {
        showVideoMessage(`No video filename in videos.json for ${record.basename || record.SourceFile || '(unknown clip)'}`);
        console.warn('[review] no video key for record', record);
        viewer.clearMedia();
        return;
    }
    const videoUrl = shared.signAWSUrl(videoKey);
    if (!videoUrl) {
        showVideoMessage(`Could not sign video URL for ${videoKey}<br><small>Check Lambda/browser console for auth or policy errors.</small>`);
        console.warn('[review] signAWSUrl failed for video', videoKey, record);
        viewer.clearMedia();
        return;
    }
    const poseUrl = record.PoseFile ? shared.signAWSUrl('Insta360/' + record.PoseFile) : null;
    const logPath = record.LogFile ? 'Insta360/' + record.LogFile : null;
    const slogPath = logPath ? logPath.slice(0, -4) + '.slog' : null;
    // Pre-sign both forms so the fail-fast UX below stays accurate; loadLog
    // tries .slog first then falls back to .log on 404. Missing slog signature
    // is fine — loadLog skips the .slog attempt when the pair lacks `slog`.
    const signedLog = logPath ? shared.signAWSUrl(logPath) : null;
    const signedSlog = slogPath ? shared.signAWSUrl(slogPath) : null;
    if (record.PoseFile && !poseUrl) console.warn('[review] signAWSUrl failed for pose', record.PoseFile, record);
    if (record.LogFile && !signedLog) console.warn('[review] signAWSUrl failed for log', record.LogFile, record);
    if (record.PoseFile && !poseUrl) {
        showVideoMessage(`Could not sign pose URL for ${record.PoseFile}<br><small>Video not switched because the 360 view would be unreliable.</small>`);
        viewer.clearMedia();
        return;
    }
    if (record.LogFile && !signedLog) {
        showVideoMessage(`Could not sign log URL for ${record.LogFile}<br><small>Video not switched because timing would be unreliable.</small>`);
        viewer.clearMedia();
        return;
    }

    currentVideoBasename = record.basename;
    currentVideoRecord = record;
    resetOverlay();
    viewer.loadVideo({
        videoUrl,
        poseUrl,
        logPath,
        signLog: logPath ? {log: signedLog, slog: signedSlog || undefined} : undefined,
        columnsMap: videosColumnsMap,
        basename: record.basename,
        startTime: targetUnixMs ? clipOffsetSeconds(record, targetUnixMs) : 0,
        autoplay: true,
        projection: record.projection,
    });
}

function clipOffsetSeconds(record, targetUnixMs) {
    const key = normalizeCreateDate(record.CreateDate);
    if (!key || !Number.isFinite(targetUnixMs)) return 0;
    const targetKey = viewer360.wallClockInTz(targetUnixMs, 'America/Los_Angeles');
    const clipStart = Date.parse(key.replace(' ', 'T') + 'Z');
    const target = Date.parse(targetKey.replace(' ', 'T') + 'Z');
    if (!Number.isFinite(clipStart) || !Number.isFinite(target)) return 0;
    return Math.max(0, (target - clipStart) / 1000);
}

function videoKeyForRecord(record) {
    const candidates = [
        record.VideoFile,
        record.MP4File,
        record.video,
        record.basename ? record.basename + '.mp4' : null,
        record.SourceFile && record.SourceFile.endsWith('.mp4') ? record.SourceFile : null,
    ].filter(Boolean);
    const first = candidates[0];
    return first ? 'Insta360/' + first : null;
}

// Polls viewer.getUnixRange() until the log is loaded (or timeout), then
// runs `fn`. Used to defer a seek until after a clip swap finishes fetching.
function whenLogReady(fn, {timeoutMs = 8000, pollMs = 50, basename = null} = {}) {
    const started = performance.now();
    const tick = () => {
        if (viewer && viewer.getUnixRange()
            && (!basename || (currentVideoBasename === basename && viewer.getLogBasename() === basename))) {
            fn();
            return;
        }
        if (performance.now() - started > timeoutMs) {
            console.warn('[review] whenLogReady: timed out waiting for log');
            return;
        }
        setTimeout(tick, pollMs);
    };
    tick();
}

function applyPendingSeek() {
    if (!pendingSeekForStart) return;
    const {s: ps, scrubberSeconds: ss} = pendingSeekForStart;
    pendingSeekForStart = null;
    pendingSeekBasename = null;
    const ok = viewer.seekToUnix((ps.start_time_unix + ss) * 1000);
    if (!ok) {
        console.warn(`[review] seekToUnix failed for ${ps.id} +${ss}s (log not loaded)`);
        return;
    }
    viewer.reset();
    updateOverlay(viewer.video.currentTime * 1000, ps);
}

function syncVideoToScrubber(s, scrubberSeconds) {
    if (!viewer) return;
    const unixMs = (s.start_time_unix + scrubberSeconds) * 1000;

    // Only swap clips when the target is outside the *video* extent, not just
    // outside the log's row_times. Some BB log slices end before the video
    // does (sensor stopped mid-clip); in that case the clip's video still
    // covers the target and seekToUnix extrapolates to the right frame.
    const range = viewer.getUnixRange();
    const videoDurMs = (viewer.video && isFinite(viewer.video.duration))
        ? viewer.video.duration * 1000 : null;
    if (range && videoDurMs) {
        const [clipStart, clipEnd] = range;
        const videoEndUnixMs = clipStart + videoDurMs;
        // If seeking forward past current clip's video, load the next clip
        if (unixMs > videoEndUnixMs && currentVideoRecord) {
            const nextClip = findNextVideoClip(currentVideoRecord);
            if (nextClip) {
                console.log(`[review] scrubber seeking past clip video end, loading ${nextClip.basename}`);
                loadVideoClip(nextClip, unixMs);
                pendingSeekForStart = {s, scrubberSeconds};
                pendingSeekBasename = nextClip.basename;
                whenLogReady(applyPendingSeek, {basename: nextClip.basename});
                return;
            }
            // No adjacent clip available — refuse to seek rather than let
            // seekToUnix extrapolate and clamp the video to its duration.
            console.warn(`[review] target +${scrubberSeconds}s is past clip video end and no next clip available; not seeking`);
            return;
        }
        // If seeking backward before current clip's video, reload the correct clip
        if (unixMs < clipStart - 5000) {
            const correctClip = viewer360.pickVideoForUnix(videosJson.videos, unixMs);
            if (correctClip && correctClip.basename !== currentVideoBasename) {
                console.log(`[review] scrubber seeking before clip start, loading ${correctClip.basename}`);
                loadVideoClip(correctClip, unixMs);
                pendingSeekForStart = {s, scrubberSeconds};
                pendingSeekBasename = correctClip.basename;
                whenLogReady(applyPendingSeek, {basename: correctClip.basename});
                return;
            }
            console.warn(`[review] target ${scrubberSeconds}s is before loaded clip start and no earlier clip available; not seeking`);
            return;
        }
        // Target is within this clip's video extent: fall through to
        // viewer.seekToUnix, which handles the log-but-not-video case by
        // extrapolating past row_times at the log's sample rate.
    }

    const ok = viewer.seekToUnix(unixMs);
    if (ok) {
        updateOverlay(viewer.video.currentTime * 1000, s);
        return;
    }

    // Log wasn't loaded yet — wait for it, then seek.
    pendingSeekForStart = {s, scrubberSeconds};
    pendingSeekBasename = currentVideoBasename;
    whenLogReady(applyPendingSeek, {basename: currentVideoBasename});
}

function renderManeuversTable(s) {
    const tacks = s.tacks || [];
    const gybes = s.gybes || [];
    const all = [...tacks.map(t => ({...t, type: 'tack'})),
        ...gybes.map(g => ({...g, type: 'gybe'}))]
        .sort((a, b) => (a.time_s || 0) - (b.time_s || 0));

    const tbody = document.getElementById('maneuver-tbody');
    if (all.length === 0) {
        tbody.innerHTML = '<tr><td colspan="11" class="no-data">No maneuvers detected.</td></tr>';
        return;
    }

    tbody.innerHTML = all.map(m => {
        const preStart = m.time_s < 0;
        const dirClass = m.direction === 'P-to-S' ? 'dir-ps' : 'dir-sp';
        const timeStr = m.time_s != null ? `${m.time_s > 0 ? '+' : ''}${m.time_s}s` : '?';
        const dHdg = m.hdg_change != null ? `${Math.round(Math.abs(m.hdg_change))}°` : '?';
        const entry = m.entry_spd_kts != null ? m.entry_spd_kts.toFixed(2) : '?';
        const minSpd = m.min_spd_kts != null ? m.min_spd_kts.toFixed(2) : '?';
        const r80 = m.spd_recovery_s_80 != null ? m.spd_recovery_s_80 + 's' : '?';
        const r90 = m.spd_recovery_s_90 != null ? m.spd_recovery_s_90 + 's' : '?';
        const lostM = m.distance_lost_m != null ? Math.round(m.distance_lost_m) : '?';
        const lostS = m.time_lost_s != null ? Math.round(m.time_lost_s) : '?';
        const yaw = m.max_yaw_rate_deg_s != null ? Math.round(m.max_yaw_rate_deg_s) + '°/s' : '?';
        const sym = m.twa_symmetry_deg != null
            ? `${m.twa_symmetry_deg > 0 ? '+' : ''}${Math.round(m.twa_symmetry_deg)}°`
            : '?';
        return `<tr class="${preStart ? 'pre-start' : ''}">
      <td>${timeStr}</td>
      <td class="tack-type">${m.type}</td>
      <td class="${dirClass}">${dirArrow(m.direction)}</td>
      <td>${dHdg}</td>
      <td>${entry}</td>
      <td>${minSpd}</td>
      <td>${r80}</td>
      <td>${r90}</td>
      <td>${lostM} / ${lostS}</td>
      <td>${yaw}</td>
      <td>${sym}</td>
    </tr>`;
    }).join('');
}

// ---- Comments -------------------------------------------------------------
function ensureAliasOrPrompt(next) {
    const cached = utils.getCookie('comment_alias');
    if (shared.isValidAlias(cached)) {
        shared.ensureAliasRegistered(cached, err => {
            if (err) {
                utils.setCookie('comment_alias', '', -1);
                alert(`Could not register alias: ${err}. Please choose a different name.`);
                return;
            }
            next(cached);
        });
        return;
    }

    let msg = 'Pick a display name for your comments.\nAllowed: letters, numbers, dash, underscore. Max 30 chars.';
    for (let attempt = 0; attempt < 3; attempt++) {
        const raw = window.prompt(msg, utils.getCookie('username') || '');
        if (raw == null) return;
        const alias = raw.trim();
        if (!shared.isValidAlias(alias)) {
            msg = `"${alias}" is not a valid alias. Use only letters, numbers, dash, underscore (1–30 chars).`;
            continue;
        }
        shared.ensureAliasRegistered(alias, (err) => {
            if (err) { alert(`Could not register alias: ${err}`); return; }
            utils.setCookie('comment_alias', alias, 365);
            next(alias);
        });
        return;
    }
}

function postStartComment() {
    if (!selectedId) return;
    const ta = document.getElementById('detail-comment-text');
    const text = (ta.value || '').trim();
    if (!text) return;
    ensureAliasOrPrompt(() => {
        shared.appendMyComment({
            text,
            target: {kind: 'review', start_id: selectedId},
        }, (err) => {
            if (err) { alert(`Comment failed: ${err}`); return; }
            ta.value = '';
            shared.loadAllComments((_, list) => {
                commentsCache = list || [];
                if (activeTab === 'comments') renderCommentsList();
                renderStartComments(selectedId);
            });
        });
    });
}

function switchTab(tab) {
    activeTab = tab;
    document.querySelectorAll('.tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
    document.querySelectorAll('[data-tab-content]').forEach(el => {
        el.style.display = el.dataset.tabContent === tab ? '' : 'none';
    });
    const listEl = document.getElementById('start-list');
    if (tab === 'comments') {
        renderCommentsList();
    } else {
        listEl.innerHTML = '';
        renderList();
    }
    // Tab is part of navigational URL state; tab toggles do not push history.
    replaceUrl({tab: tab === 'comments' ? URL_TAB_COMMENTS : URL_TAB_EVENTS});
}

function renderCommentsList() {
    const container = document.getElementById('start-list');
    container.innerHTML = '';
    if (commentsCache == null) {
        container.innerHTML = '<div class="no-data" style="padding:20px;text-align:center">Loading…</div>';
        return;
    }
    if (commentsCache.length === 0) {
        container.innerHTML = '<div class="no-data" style="padding:20px;text-align:center">No comments yet.</div>';
        return;
    }
    for (const c of commentsCache) container.appendChild(buildCommentCard(c));
}

function buildCommentCard(c) {
    const div = document.createElement('div');
    div.className = 'comment-card';
    const when = c.created_ts ? formatDate(c.created_ts) : '';
    const target = c.target || {};
    let targetLabel = '—';
    if (target.kind === 'sailview') {
        const t = Number(target.t || 0);
        targetLabel = `Sailview · ${target.video || ''} @ ${t.toFixed(1)}s`;
    } else if (target.kind === 'review') {
        targetLabel = `Start · ${target.start_id || ''}`;
    }

    div.innerHTML = `
      <div class="comment-head">
        <span class="comment-alias">${utils.htmlEncode(c.alias || '?')}</span>
        <span class="comment-time">${when}</span>
      </div>
      <div class="comment-body">${utils.htmlEncode(c.text || '')}</div>
      <div class="comment-target">${utils.htmlEncode(targetLabel)}</div>
      <div class="comment-actions"></div>
    `;
    const actions = div.querySelector('.comment-actions');

    if (target.kind === 'sailview' && target.video) {
        [5, 30, 120].forEach(delta => {
            const btn = document.createElement('button');
            btn.className = 'card-btn';
            btn.title = `Open sailview at t−${delta}s`;
            btn.textContent = `−${delta}s`;
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                const seek = Math.max(0, (Number(target.t) || 0) - delta);
                const url = `sailview.html?video=${encodeURIComponent(target.video)}&time=${seek}`;
                window.open(url, '_blank');
            });
            actions.appendChild(btn);
        });
    } else if (target.kind === 'review' && target.start_id) {
        const btn = document.createElement('button');
        btn.className = 'card-btn';
        btn.textContent = 'Open start';
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            switchTab('starts');
            const s = (startsData.starts || []).find(x => x.id === target.start_id);
            if (s) selectStart(s.id);
        });
        actions.appendChild(btn);
    }
    return div;
}

function renderStartComments(startId) {
    const container = document.getElementById('detail-comments-list');
    if (!container) return;
    const forStart = (commentsCache || []).filter(c =>
        c.target && c.target.kind === 'review' && c.target.start_id === startId);
    if (forStart.length === 0) {
        container.innerHTML = '<div class="no-data">No comments on this start yet.</div>';
        return;
    }
    container.innerHTML = forStart.map(c => {
        const when = c.created_ts ? formatDate(c.created_ts) : '';
        return `<div class="detail-comment">
            <span class="comment-alias">${utils.htmlEncode(c.alias || '?')}</span>
            <span class="comment-time">${when}</span>
            <div class="comment-body">${utils.htmlEncode(c.text || '')}</div>
        </div>`;
    }).join('');
}

// ---- Status management ----------------------------------------------------
function setStatus(id, newStatus) {
    const s = (startsData.starts || []).find(x => x.id === id);
    if (!s) return;
    s.status = newStatus;
    upsertEdit(id, {status: newStatus});
    updateStatusInPlace(id);
    saveData({silent: true});
}

function updateStatusInPlace(id) {
    const s = (startsData.starts || []).find(x => x.id === id);
    if (!s) return;
    renderStats();

    const card = document.querySelector(`.start-card[data-id="${id}"]`);
    if (card) {
        card.classList.toggle('pending', s.status === 'pending');
        card.classList.toggle('confirmed', s.status === 'confirmed');
        card.classList.toggle('discarded', s.status === 'discarded');
        const badge = card.querySelector('.card-badges .badge:first-child');
        if (badge) {
            badge.className = `badge badge-${s.status}`;
            badge.textContent = s.status;
        }
        const confirm = card.querySelector('.card-btn-confirm');
        const discard = card.querySelector('.card-btn-discard');
        if (confirm) confirm.classList.toggle('active', s.status === 'confirmed');
        if (discard) discard.classList.toggle('active', s.status === 'discarded');
    }

    if (selectedId === id) {
        const confirmBtn = document.getElementById('btn-confirm');
        const discardBtn = document.getElementById('btn-discard');
        if (confirmBtn) confirmBtn.classList.toggle('active', s.status === 'confirmed');
        if (discardBtn) discardBtn.classList.toggle('active', s.status === 'discarded');
    }
}

// ---- Wind-relative view ---------------------------------------------------
function getAvgTwd(s) {
    const twdSource = s.twd_series && s.twd_series.length > 0 ? s.twd_series : null;
    if (!twdSource) return null;
    const twdValues = twdSource.filter(p => p[0] >= 0 && p[0] <= 120).map(p => p[1]);
    if (twdValues.length === 0) return null;
    const sinSum = twdValues.reduce((sum, a) => sum + Math.sin(a * Math.PI / 180), 0);
    const cosSum = twdValues.reduce((sum, a) => sum + Math.cos(a * Math.PI / 180), 0);
    return (Math.atan2(sinSum, cosSum) * 180 / Math.PI + 360) % 360;
}

function toggleWindView() {
    windViewMode = !windViewMode;
    document.getElementById('toggle-wind-view').textContent =
        windViewMode ? 'Geographic View' : 'Wind-Relative View';
    if (selectedId) {
        const s = (startsData.starts || []).find(x => x.id === selectedId);
        if (s) applyMapRotation(s);
    }
}

function applyMapRotation(s) {
    if (!detailMap) return;
    if (typeof detailMap.setBearing !== 'function') {
        console.warn('Map rotation not available - leaflet-rotate plugin may not be loaded');
        return;
    }
    if (!windViewMode) { detailMap.setBearing(0); return; }
    const windDir = getAvgTwd(s) || 0;
    const bearing = -windDir;
    console.log(`Wind-relative rotation: TWD=${windDir.toFixed(1)}°, setBearing(${bearing.toFixed(1)})`);
    detailMap.setBearing(bearing);
}

// Updates the time label, map marker, and chart cursor for a given scrubber
// position (seconds relative to start). Does NOT seek the video — used both
// by user scrub events and by the video's own timeupdate events.
function applyScrubberUI(time) {
    const sign = time >= 0 ? '+' : '';
    document.getElementById('detail-scrubber-time').textContent = `${sign}${time.toFixed(0)}s`;
    if (detailFullTrack && detailScrubberMarker) updateDetailScrubberPosition(time);
    redrawChartsWithCursor(time);
    if (aisEnabled) updateAisLayer(time);
}

// ---- AIS overlay ----------------------------------------------------------
function aisColorFor(mmsi) {
    // Stable hash → HSL so the same boat keeps its color across scrub ticks.
    let h = 0;
    const s = String(mmsi);
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) & 0xffff;
    return `hsl(${h % 360}, 70%, 55%)`;
}

function aisEscape(s) {
    return String(s).replace(/[&<>"']/g, ch => (
        {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]
    ));
}

function clearAisLayers() {
    for (const mmsi in aisLayers) {
        const g = aisLayers[mmsi];
        if (g.trail) g.trail.remove();
        if (g.marker) g.marker.remove();
    }
    aisLayers = {};
    renderAisLegend();
}

function hideAisBoat(mmsi) {
    const g = aisLayers[mmsi];
    if (!g) return;
    if (g.trail) { g.trail.remove(); g.trail = null; }
    if (g.marker) { g.marker.remove(); g.marker = null; }
}

function aisBoatDisplayName(boat) {
    const name = (boat.name && boat.name.trim()) || '';
    return name || `MMSI ${String(boat.mmsi).slice(-4)}`;
}

function renderAisLegend() {
    const el = document.getElementById('ais-legend');
    if (!el) return;
    if (!aisEnabled || !aisBoats || aisBoats.length === 0) {
        el.style.display = 'none';
        el.innerHTML = '';
        return;
    }
    el.style.display = '';
    const rows = aisBoats.map(b => {
        const mmsi = String(b.mmsi);
        const color = aisColorFor(mmsi);
        const name = aisEscape(aisBoatDisplayName(b));
        const dist = (typeof b.min_dist_m === 'number') ? ` <span class="ais-legend-dist">${Math.round(b.min_dist_m)}m</span>` : '';
        return `<div class="ais-legend-row"><span class="ais-legend-swatch" style="background:${color}"></span>${name}${dist}</div>`;
    });
    el.innerHTML = `<div class="ais-legend-title">Nearby (AIS)</div>${rows.join('')}`;
}

// Called on every scrubber tick. Rebuilds (or updates in place) per-boat layers
// for the currently selected start. Trail = last AIS_TRAIL_SAMPLES real samples
// at/before tNow, followed by the interpolated current position.
function updateAisLayer(relTime) {
    if (!detailMap || !aisEnabled || !aisBoats || !selectedId) return;
    const s = (startsData.starts || []).find(x => x.id === selectedId);
    if (!s) return;
    const tNow = s.start_time_unix + relTime;

    for (const boat of aisBoats) {
        const track = boat.track || [];
        if (track.length === 0) continue;
        const mmsi = String(boat.mmsi);

        // Binary search for the last sample with ts <= tNow.
        let lo = 0, hi = track.length - 1, prevIdx = -1;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (track[mid][2] <= tNow) { prevIdx = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        const prev = prevIdx >= 0 ? track[prevIdx] : null;
        const next = prevIdx + 1 < track.length ? track[prevIdx + 1] : null;

        let curLat = null, curLon = null;
        if (prev && next) {
            const dt = next[2] - prev[2];
            const within = (tNow - prev[2] <= AIS_MAX_GAP_SEC) || (next[2] - tNow <= AIS_MAX_GAP_SEC);
            if (dt > 0 && within) {
                const f = Math.max(0, Math.min(1, (tNow - prev[2]) / dt));
                curLat = prev[0] * (1 - f) + next[0] * f;
                curLon = prev[1] * (1 - f) + next[1] * f;
            }
        } else if (prev && tNow - prev[2] <= AIS_MAX_GAP_SEC) {
            curLat = prev[0]; curLon = prev[1];
        } else if (next && next[2] - tNow <= AIS_MAX_GAP_SEC) {
            curLat = next[0]; curLon = next[1];
        }

        if (curLat === null) { hideAisBoat(mmsi); continue; }

        const trailPts = [];
        if (prevIdx >= 0) {
            const firstIdx = Math.max(0, prevIdx - (AIS_TRAIL_SAMPLES - 1));
            for (let i = firstIdx; i <= prevIdx; i++) trailPts.push([track[i][0], track[i][1]]);
        }
        trailPts.push([curLat, curLon]);

        const color = aisColorFor(mmsi);
        let g = aisLayers[mmsi];
        if (!g) g = aisLayers[mmsi] = {};

        if (trailPts.length >= 2) {
            if (g.trail) g.trail.setLatLngs(trailPts);
            else g.trail = L.polyline(trailPts, {color, weight: 2, opacity: 0.75}).addTo(detailMap);
        } else if (g.trail) {
            g.trail.remove(); g.trail = null;
        }

        if (g.marker) g.marker.setLatLng([curLat, curLon]);
        else g.marker = L.circleMarker([curLat, curLon], {
            radius: 5, color: '#fff', weight: 1.5, fillColor: color, fillOpacity: 1.0,
        }).addTo(detailMap).bindTooltip(aisEscape(aisBoatDisplayName(boat)), {direction: 'top', offset: [0, -4]});
    }
}

function toggleAisView() {
    aisEnabled = !aisEnabled;
    const btn = document.getElementById('toggle-ais-view');
    if (btn) btn.textContent = aisEnabled ? 'Hide AIS' : 'Show AIS';
    if (aisEnabled) { updateAisLayer(currentScrubberValue()); renderAisLegend(); }
    else { clearAisLayers(); renderAisLegend(); }
}

function onDetailScrub() {
    const time = parseFloat(document.getElementById('detail-scrubber-range').value);
    applyScrubberUI(time);

    if (selectedId) {
        const s = (startsData.starts || []).find(x => x.id === selectedId);
        if (s) syncVideoToScrubber(s, time);
    }

    // Debounced URL update — scrubbing fires per-pixel input events, so we
    // batch them to avoid hundreds of replaceState calls per drag.
    if (scrubUrlDebounceTimer) clearTimeout(scrubUrlDebounceTimer);
    scrubUrlDebounceTimer = setTimeout(() => {
        replaceUrl({t: Number.isFinite(time) ? time : 0});
    }, 300);
}

// ---- Save -----------------------------------------------------------------
// Writes only the small edits overlay (events_edits.json); the generated
// events_index.json + per-event detail files are read-only from the pipeline.
function saveData({silent = false} = {}) {
    const btn = document.getElementById('save-btn');
    if (!silent) {
        btn.textContent = 'Saving...';
        btn.disabled = true;
    }
    return new Promise((resolve, reject) => {
        shared.putDataJSON('Analyze/events_edits.json', editsData, (err) => {
            if (err) {
                btn.textContent = 'Error ✗';
                btn.disabled = false;
                alert(`Save failed: ${err}`);
                reject(err);
                return;
            }
            if (!silent) {
                btn.textContent = 'Saved ✓';
                setTimeout(() => { btn.textContent = 'Save'; btn.disabled = true; }, 2000);
            } else {
                btn.disabled = true;
            }
            resolve();
        });
    });
}

// ---- Helpers --------------------------------------------------------------
function formatDate(unix) {
    if (!unix) return '?';
    const d = new Date(unix * 1000);
    return d.toLocaleString('en-US', {
        weekday: 'short', year: 'numeric', month: 'short', day: 'numeric',
        hour: '2-digit', minute: '2-digit', timeZone: 'America/Los_Angeles',
    });
}

// ---- Away pause -----------------------------------------------------------
// Auto-pause when the user isn't watching (Space switch, ⌘-Tab, tab switch,
// minimize). Each MP4 is ~2 GB so unwatched playback burns S3 egress fast.
// Mirrors the sailview behavior; both pages serve the same clips from the
// same bucket. blur/focus catches Space switch and ⌘-Tab (tab still
// "visible"); visibilitychange catches tab switch and minimize. Resume +
// hide overlay only if WE paused (don't fight a manual pause).
function installAwayPause() {
    const overlay = document.getElementById('awayOverlay');
    let pausedByAway = false;

    const isAway = () => document.hidden || !document.hasFocus();

    const onAway = () => {
        if (!viewer || viewer.video.paused || pausedByAway) return;
        pausedByAway = true;
        viewer.video.pause();
        if (overlay) overlay.style.display = 'flex';
    };

    const onBack = () => {
        if (!pausedByAway) return;
        pausedByAway = false;
        if (overlay) overlay.style.display = 'none';
        if (viewer) viewer.video.play().catch(() => {});
    };

    window.addEventListener('blur', onAway);
    window.addEventListener('focus', () => { if (!isAway()) onBack(); });
    document.addEventListener('visibilitychange', () => {
        if (document.hidden) onAway();
        else if (!isAway()) onBack();
    });
}

// ---- DOM wiring -----------------------------------------------------------
document.addEventListener('DOMContentLoaded', () => {
    document.getElementById('save-btn').addEventListener('click', () => saveData());
    restoreFilterState();
    document.getElementById('filter-status').addEventListener('change', onFilterChanged);
    document.getElementById('sort-by').addEventListener('change', onFilterChanged);

    // Day picker: click toggle to open/close; click outside or press Escape
    // to close. Day-button clicks (added in populateDayPicker) handle their
    // own selection-and-close, and stopPropagation isn't needed because the
    // outside-click handler bails when the click is inside #day-picker.
    const dayPickerToggle = document.getElementById('day-picker-toggle');
    const dayPickerRoot = document.getElementById('day-picker');
    if (dayPickerToggle && dayPickerRoot) {
        dayPickerToggle.addEventListener('click', (e) => {
            e.stopPropagation();
            const panel = document.getElementById('day-picker-panel');
            if (panel.hidden) openDayPicker(); else closeDayPicker();
        });
        document.addEventListener('click', (e) => {
            if (!dayPickerRoot.contains(e.target)) closeDayPicker();
        });
        document.addEventListener('keydown', (e) => {
            const panel = document.getElementById('day-picker-panel');
            if (e.key === 'Escape' && panel && !panel.hidden) closeDayPicker();
        });
    }
    document.querySelectorAll('.kind-filter-check').forEach(c => {
        c.addEventListener('change', onFilterChanged);
    });
    document.getElementById('toggle-wind-view').addEventListener('click', toggleWindView);
    const aisBtn = document.getElementById('toggle-ais-view');
    if (aisBtn) aisBtn.addEventListener('click', toggleAisView);
    const scrubEl = document.getElementById('detail-scrubber-range');
    scrubEl.addEventListener('input', onDetailScrub);
    // Belt-and-suspenders: handleKeyDown already lets non-text INPUTs through,
    // but releasing focus avoids the ugly focus ring + native arrow-step on
    // the slider competing with our ArrowLeft/Right frame-step bindings.
    scrubEl.addEventListener('change', () => scrubEl.blur());
    document.getElementById('detail-play-btn').addEventListener('click', togglePlay);
    wireChromeBar();

    // Tabs
    document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.addEventListener('click', () => switchTab(btn.dataset.tab));
    });

    // Comment composer in detail pane.
    const composerSubmit = document.getElementById('detail-comment-submit');
    if (composerSubmit) composerSubmit.addEventListener('click', postStartComment);
    const composerEdit = document.getElementById('detail-comment-edit-alias');
    if (composerEdit) composerEdit.addEventListener('click', () => {
        utils.eraseCookie('comment_alias');
        ensureAliasOrPrompt(() => {});
    });

    // popstate: back/forward navigation. Re-parse the URL, diff against the
    // current state, and apply changes WITHOUT recursing into pushUrl/replaceUrl
    // (the popstateInProgress guard makes those no-ops for the duration of
    // this handler).
    window.addEventListener('popstate', () => {
        const next = parseUrlState();
        const prev = currentUrlState;
        popstateInProgress = true;
        try {
            currentUrlState = next;

            const filtersChanged = (
                next.status !== prev.status
                || next.day !== prev.day
                || next.sort !== prev.sort
                || !_kindSetEquals(next.kindSet, prev.kindSet)
            );
            if (filtersChanged) {
                const setSelectValue = (id, value) => {
                    if (!value) return;
                    const el = document.getElementById(id);
                    if (el && Array.from(el.options).some(o => o.value === value)) el.value = value;
                };
                setSelectValue('filter-status', next.status);
                setSelectValue('sort-by', next.sort);
                applyKindSetToDom(next.kindSet);
                selectedDay = next.day && next.day !== 'all' ? next.day : null;
                refreshDayPickerLabel();
                document.querySelectorAll('#day-picker-panel .dp-item.selected')
                    .forEach(el => el.classList.remove('selected'));
                const target = selectedDay
                    ? document.querySelector(`#day-picker-panel .dp-item[data-day="${selectedDay}"]`)
                    : document.querySelector('#day-picker-panel .dp-item-all');
                if (target) target.classList.add('selected');
                saveFilterState();  // localStorage mirror
            }

            const tabUi = next.tab === URL_TAB_COMMENTS ? 'comments' : 'starts';
            if (tabUi !== activeTab) {
                activeTab = tabUi;
                document.querySelectorAll('.tab-btn').forEach(b =>
                    b.classList.toggle('active', b.dataset.tab === activeTab));
                document.querySelectorAll('[data-tab-content]').forEach(el => {
                    el.style.display = el.dataset.tabContent === activeTab ? '' : 'none';
                });
            }

            if (next.event && next.event !== selectedId) {
                // selectStart() will call pushUrl() — that's a no-op while
                // popstateInProgress is true, so we re-use it for free.
                const target = (startsData.starts || []).find(s => s.id === next.event);
                if (target) selectStart(next.event);
                else { selectedId = next.event; renderAll(); }
            } else if (filtersChanged) {
                renderAll();
            }

            // Apply scrubber position if changed.
            if (Number.isFinite(next.t) && selectedId) {
                const scrubber = document.getElementById('detail-scrubber-range');
                if (scrubber && parseFloat(scrubber.value) !== next.t) {
                    scrubber.value = next.t;
                    onDetailScrub();
                }
            }
        } finally {
            popstateInProgress = false;
        }
    });

    installAwayPause();

    // Keyboard shortcuts - use capture phase to get events before Leaflet/other handlers
    window.addEventListener('keydown', handleKeyDown, true);

    // Blur buttons after click so they don't capture keyboard focus (event delegation
    // handles dynamically created buttons too)
    document.addEventListener('click', (e) => {
        if (e.target.tagName === 'BUTTON') {
            e.target.blur();
        }
    });

    boot();
});

// ---- Keyboard shortcuts ---------------------------------------------------
const FRAME_DURATION = 1 / 30; // ~33ms per frame at 30fps
const SKIP_SECONDS = 5;

// Text-entry input types we should NOT intercept keys from. A range slider
// is also an INPUT but should yield to viewer shortcuts, otherwise clicking
// the scrubber traps every subsequent key (no more f/r/p) until the user
// clicks elsewhere.
const TEXT_INPUT_TYPES = new Set([
    'text', 'search', 'email', 'password', 'number', 'url', 'tel',
    'date', 'time', 'datetime-local',
]);

function handleKeyDown(e) {
    const tag = (e.target && e.target.tagName) || '';

    // Don't intercept typing in form fields
    if (tag === 'TEXTAREA' || tag === 'SELECT') return;
    if (tag === 'INPUT') {
        const t = (e.target.type || 'text').toLowerCase();
        if (TEXT_INPUT_TYPES.has(t)) return;
    }

    // Escape closes help overlay
    if (e.key === 'Escape') {
        const overlay = document.getElementById('help-overlay');
        if (overlay && overlay.style.display !== 'none') {
            overlay.style.display = 'none';
            e.preventDefault();
            return;
        }
    }

    const action = keyActions[e.key];
    if (action) {
        e.preventDefault();
        e.stopPropagation();
        
        // Blur any focused element (buttons, Leaflet controls, etc.) to prevent
        // them from capturing subsequent key events
        if (document.activeElement && document.activeElement !== document.body) {
            document.activeElement.blur();
        }
        
        action();
    }
}

const keyActions = {
    ' ': () => togglePlay(),

    'ArrowLeft': () => {
        if (!viewer) return;
        viewer.video.pause();
        viewer.video.currentTime = Math.max(0, viewer.video.currentTime - FRAME_DURATION);
    },

    'ArrowRight': () => {
        if (!viewer) return;
        viewer.video.pause();
        viewer.video.currentTime = Math.min(
            viewer.video.duration || Infinity,
            viewer.video.currentTime + FRAME_DURATION
        );
    },

    'ArrowDown': () => {
        if (!viewer) return;
        viewer.video.currentTime = Math.max(0, viewer.video.currentTime - SKIP_SECONDS);
    },

    'ArrowUp': () => {
        if (!viewer) return;
        viewer.video.currentTime = Math.min(
            viewer.video.duration || Infinity,
            viewer.video.currentTime + SKIP_SECONDS
        );
    },

    'd': () => {
        if (!viewer) return;
        const newRate = Math.min(4, viewer.video.playbackRate * 1.1);
        viewer.video.playbackRate = newRate;
        console.log(`[review] playback speed: ${newRate.toFixed(2)}x`);
    },

    's': () => {
        if (!viewer) return;
        const newRate = Math.max(0.25, viewer.video.playbackRate * 0.9);
        viewer.video.playbackRate = newRate;
        console.log(`[review] playback speed: ${newRate.toFixed(2)}x`);
    },

    'm': () => {
        if (!viewer) return;
        viewer.video.muted = !viewer.video.muted;
    },

    'r': () => { if (viewer) viewer.reset(); },
    'f': () => { if (viewer) viewer.flip(); },
    'p': () => {
        if (!viewer) return;
        viewer.setSkipFrames(!viewer.getSkipFrames());
    },

    'c': () => {
        // The URL is now authoritative for navigation state — every visible
        // selection / filter / scrub position is already reflected there.
        const fullUrl = window.location.href;
        navigator.clipboard.writeText(fullUrl).then(() => {
            console.log('[review] copied URL:', fullUrl);
        }).catch(err => {
            console.warn('[review] clipboard write failed:', err);
        });
    },

    'h': () => toggleHelpOverlay(),
};

function toggleHelpOverlay() {
    const overlay = document.getElementById('help-overlay');
    if (!overlay) return;
    overlay.style.display = overlay.style.display === 'none' ? 'flex' : 'none';
}
